 const points=path=>path.map(s=>`${px(s).toFixed(3)},${py(s).toFixed(3)}`).join(' '),clip='cycle-clip-'+kind,inside=s=>px(s)>=100&&px(s)<=700&&py(s)>=45&&py(s)<=325;
 // Nearby pump states and overlaid variants need separate readable labels.
