  const result=mix?{states:[x,z],path:[x,z],schematic:true,mixing:true,heat:0,technicalWork:0,boundaryWork:null,converged:true,tolerance:0,flowResidual:null}:kind==='adiabatic'?adiabaticMachine(x,z.p,p.eta,model):solveWaterProcess({fluid:'water',mass:1,mode:p.mode,a:p.a,b:p.b,kind:'isobaric',end:'h',value:z.h},model);
