 dynamicViscosity:{auto:['За системою',null,0],Pas:['Pa·s',1,0],uPas:['μPa·s',1e-6,0],lb_fts:['lb/(ft·s)',UNIT_LB/UNIT_FT,0],lb_fth:['lb/(ft·h)',UNIT_LB/(UNIT_FT*3600),0]},
