// Continuity and Reynolds number for a single-phase Newtonian fluid in a round pipe.
// NASA Glenn: https://www.grc.nasa.gov/WWW/K-12/airplane/reynolds.html
const FLOW_UNITS={mass:{kgs:1,kgh:1/3600,lbs:.45359237,lbh:.45359237/3600},volume:{m3s:1,m3h:1/3600,ls:.001,lmin:.001/60,ft3min:.3048**3/60},velocity:{ms:1,fts:.3048},diameter:{m:1,mm:.001,inch:.0254},length:{m:1,ft:.3048},pressureDrop:{Pa:1,kPa:1000,MPa:1e6,bar:1e5,psi:6894.757293168},density:{kgm3:1,lbft3:.45359237/.3048**3},dynamic:{Pas:1,mPas:.001,cP:.001},kinematic:{m2s:1,mm2s:1e-6,cSt:1e-6}};
