// src/reactor-verification.js
const REACTOR_EVIDENCE_VERSION='reactor-evidence-1';
const REACTOR_CHECK_SOURCES={
 iaea:'https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1264_web.pdf (Table 14.9; Appendix IV.3)',
 pin:'https://tmap8.inl.gov/docs/PRs/451/site/verification_and_validation/ver-1m.html (Table 1; analytical solution)',
 chf:'https://arxiv.org/html/2203.15048 (Eq. 53; Table 10)',
 guide:'Кравченко / Kravchenko, 2025, supplied coursework guide §3–7'
};
function reactorReferenceCellInput(index,supplementary=null){
 const ref=REACTOR_CELL_REFERENCE,c=ref.cases[index],g=ref.geometry,f=ref.atomDensitiesPerCM3.fuel,z=ref.atomDensitiesPerCM3.clad;
 const V0=Math.PI*g.fuelRadiusCM**2,Vgas=Math.PI*(g.cladInnerRadiusCM**2-g.fuelRadiusCM**2),Vzr=Math.PI*(g.cladOuterRadiusCM**2-g.cladInnerRadiusCM**2);
 const pitch=supplementary?.pitchCM??g.pitchCM,Vcell=supplementary?Math.sqrt(3)/2*pitch*pitch:Math.PI*g.cellRadiusCM**2;
 return {geometry:{fuelAreaCM2:V0,gasAreaCM2:Vgas,metalAreaCM2:Vzr,totalAreaCM2:Vcell,fuelDiameterCM:2*g.fuelRadiusCM,boreDiameterCM:0,cladDiameterCM:2*g.cladOuterRadiusCM,pitchCM:pitch,lattice:'hex'},material:{rhoWater:c.waterAtomDensitiesPerCM3.O16*18.01528/6.02214076e23,fuelDensity:g.fuelDensityGCM3,N5:f.U235,N8:f.U238,NO:f.O16,NZr:z.Zr*Vzr/(Vgas+Vzr),Nwater:c.waterAtomDensitiesPerCM3.O16},temperature:{waterK:c.temperatureK,fuelC:c.temperatureK-273.15},options:{resonanceMethod:'gp',resonanceI8:22,bellFactor:1.27,squareBoundaryGamma:1},leakage:{materialBucklingCM2:(supplementary?.measuredBucklingM2??c.measuredBucklingM2)/1e4}};
}
function reactorWorse(worst,check){const score=r=>r.status==='unavailable'?Infinity:r.absoluteError/r.tolerance;return !worst||score(check)>score(worst);}
function reactorCheck(id,kind,actual,expected,absoluteTolerance,relativeTolerance,unit,source,formula,substitution,inputs={}){
 const error=Math.abs(actual-expected),tolerance=absoluteTolerance+relativeTolerance*Math.abs(expected),valid=[actual,expected,error,tolerance].every(Number.isFinite);
 return {id,kind,actual,expected,absoluteTolerance,relativeTolerance,tolerance,absoluteError:valid?error:null,status:valid?(error<=tolerance?'passed':'failed'):'unavailable',unit,source,formula,substitution,inputs};
}
function reactorReferenceChecks(){
 const rows=[],N=v=>Number(v.toPrecision(9));
 for(const [index,c] of REACTOR_CELL_REFERENCE.cases.entries()){
  const input=reactorReferenceCellInput(index),n=reactorNeutronCell(input);
  rows.push({...reactorCheck(c.code,'physical-screening',n.keff,c.experimentalK,c.reportedKError,0,'–',REACTOR_CHECK_SOURCES.iaea,'k = k∞ exp(−B²τ)/(1+B²L²)',`${N(n.kinf)} exp(−${N(n.Bsq)} × ${N(n.age)}) / (1 + ${N(n.Bsq)} × ${N(n.Lsq)})`,input),screeningGoal:.01,withinScreeningGoal:Math.abs(n.keff-1)<=.01,diagnostics:{kinf:n.kinf,thermal:n.kinfThermal,resonance:n.kinfResonance,nonLeak:n.nonLeak,age:n.age,Lsq:n.Lsq,I8Barn:n.baseI8,Tng:n.Tng},inputBasis:'official-deck-transcription',omissions:REACTOR_CELL_REFERENCE.modelOmissions});
 }
 for(const c of REACTOR_CELL_SUPPLEMENTARY){const input=reactorReferenceCellInput(c.temperatureCase,c),n=reactorNeutronCell(input);
  rows.push({...reactorCheck(c.code,'reconstructed-screening',n.keff,c.experimentalK,c.reportedKError,0,'–',REACTOR_CHECK_SOURCES.iaea,'Acell = √3 S²/2; k = k∞ exp(−B²τ)/(1+B²L²)',`S=${c.pitchCM} cm; B²=${c.measuredBucklingM2} m⁻²`,input),inputBasis:'derived-hex-area-and-reused-unborated-materials',notes:'Not an exact deck replay: equivalent hexagonal cell area derived from pitch; unborated atom densities reused at the same temperature. Full supplemental deck unavailable on 2026-10-14.',omissions:REACTOR_CELL_REFERENCE.modelOmissions});
 }
 for(const c of REACTOR_PIN_CHECKS){const q=c.linear,rf=.005,ri=.0051,ro=.0061;
  const outer=290+q/(2*Math.PI*ro*18000),inner=outer+reactorTemperatureRise(outer,q*Math.log(ro/ri)/(2*Math.PI),'clad',16.5).rise,surface=inner+q/(2*Math.PI*rf*7381),centre=surface+reactorTemperatureRise(surface,q/(4*Math.PI),'fuel',17.6).rise;
  for(const [key,value] of Object.entries({cladOuter:outer,cladInner:inner,fuelSurface:surface,fuelCentre:centre}))rows.push(reactorCheck('pin-'+q+'-'+key,'analytical',value,c.expected[key],1e-8,1e-10,'°C',REACTOR_CHECK_SOURCES.pin,'Tco=Tb+q′/(2πroα); Tci=Tco+q′ln(ro/ri)/(2πλc); Tfs=Tci+q′/(2πrfhgap); Tc=Tfs+q′/(4πλf)',`q′=${q} W/m; rf=${rf} m; ri=${ri} m; ro=${ro} m; α=18000 W/(m² K); λc=16.5, λf=17.6 W/(m K); hgap=7381 W/(m² K); Tb=290 °C`,{linear:q,material:'U-ZrH, constant properties; not UO2 validation',gapConductance:7381,gapConductanceUnit:'W/(m² K)',coolantAlpha:18000,coolantAlphaBasis:'Estimate in the source table'}));
 }
 for(const c of REACTOR_CHF_CHECKS)rows.push(reactorCheck('chf-'+c.p,'correlation-arithmetic',reactorCHF(c.p,c.G,c.x).qCritical,c.expected,1e-10,1e-10,'MW/m²',REACTOR_CHECK_SOURCES.chf,'qcrit = 0.795 (1−x)^(0.105p−0.5) G^(0.184−0.311x) (1−0.0185p)',`p=${c.p} MPa; G=${c.G} kg/(m² s); x=${c.x}`,{...c,meaning:'Published local inputs; high-precision equation evaluation, not measured CHF'}));
 return {version:REACTOR_EVIDENCE_VERSION,arithmeticStatus:rows.filter(r=>['analytical','correlation-arithmetic'].includes(r.kind)).every(r=>r.status==='passed')?'passed':'failed',physicalStatus:rows.filter(r=>r.kind==='physical-screening').every(r=>r.status==='passed')?'screening-passed-not-full-validation':'physical-screening-failed',checks:rows,uncovered:['evaluated multigroup transport','borated lattice benchmarks','experimental bundle CHF','boiling onset for this bundle','campaign / rods / boron physical validation']};
}
// Independently reconstruct closures from the current calculated fields. A small
// residual checks equation consistency, not empirical model applicability.
function reactorCalculationChecks(q){
 const m=q.metrics,g=q.geometry,a=q.input,rows=[],add=(...args)=>rows.push(reactorCheck(...args)),N=v=>Number(v.toPrecision(9));
 add('energy','balance',m.flow*(q.states[1].h-q.states[0].h),1000*m.thermalMW,1e-7,1e-10,'kW',REACTOR_CHECK_SOURCES.guide+' §3.1','G(hout−hin) = 1000Q',`${N(m.flow)} × (${N(q.states[1].h)} − ${N(q.states[0].h)})`);
 add('power-profile','balance',m.peakLinear*1000*2*Math.sin(m.beta*m.height/2)/m.beta*m.bundles*g.rods,m.thermalMW*1e6*a.fuelFraction*a.radialPeak,1e-6,1e-10,'W',REACTOR_CHECK_SOURCES.guide+' §3.3','∫q′max cos(βz) dz × nTVS nrod = Q fFuel Krad',`${N(m.peakLinear*1000)} × 2sin(${N(m.beta*m.height/2)}) / ${N(m.beta)} × ${m.bundles} × ${g.rods}`);
 for(const [key,unit,formula,evaluate] of [
  ['clad','W/m','λclad(Tci−Tco)=Kλq′ln(d/di)/(2π)',r=>[r.cladLambda*(r.cladInner-r.cladOuter),a.conductionFactor*r.qLinear*1000*Math.log(g.d/g.di)/(2*Math.PI)]],
  ['fuel','W/m','λfuel(Tmax−Tsurface)=Kλq′Fannulus/(4π)',r=>{const x=g.hole/g.df,d=(g.df-g.hole)/g.df;let F=x===0?1:1+2*x*x*Math.log(x)/(1-x*x);if(x>.99){const n=32,f=u=>u*(2*x+d*u)/(x+d*u);let sum=f(0)+f(1);for(let i=1;i<n;i++)sum+=(i%2?4:2)*f(i/n);F=2*d/(1+x)*sum/(3*n);}return [r.fuelLambda*(r.fuelCenter-r.fuelSurface),a.conductionFactor*r.qLinear*1000*F/(4*Math.PI)];}],
  ['gap',a.gapMethod==='perfect'?'K':'W/m',a.gapMethod==='perfect'?'Tfs−Tci=0':a.gapMethod==='contact'?'π df hgap(Tfs−Tci)=Kλq′':'2πλgap(Tfs−Tci)/ln(di/df)=Kλq′',r=>a.gapMethod==='perfect'?[r.fuelSurface-r.cladInner,0]:[a.gapMethod==='contact'?Math.PI*g.df*a.contactConductance*(r.fuelSurface-r.cladInner):2*Math.PI*r.gapLambda*(r.fuelSurface-r.cladInner)/Math.log(g.di/g.df),a.conductionFactor*r.qLinear*1000]],
  ['wall','W/m²','α(Twall−Tbase)=qdrive',r=>[r.alpha*(r.cladOuter-(r.boiling?r.saturationC:r.t)),(r.boiling?r.excessFlux:r.designFlux)*1e6]]
 ]){let worst=null;for(const [channel,list] of [['hot',q.profile],['mean',q.meanProfile]])for(const r of list){const [actual,expected]=evaluate(r),check=reactorCheck(key,'equation-residual',actual,expected,1e-7,1e-9,unit,REACTOR_CHECK_SOURCES.guide+' §3.3',formula,`z=${N(r.z)} m; channel=${channel}; actual=${N(actual)}; expected=${N(expected)}`);if(reactorWorse(worst,check))worst={...check,channel,z:r.z};}rows.push(worst);}
 add('pressure-sum','balance',m.calculatedDrop,m.frictionDrop+m.localDrop+m.gravityDrop+m.accelerationDrop,1e-12,1e-10,'MPa',REACTOR_CHECK_SOURCES.guide+' §3.5','Δp=Δpf+Δplocal+Δpg+Δpa',`${N(m.frictionDrop)} + ${N(m.localDrop)} + ${N(m.gravityDrop)} + ${N(m.accelerationDrop)}`);
 if(q.chf&&a.chfMethod==='gidropress'){let worst=null;for(const [i,r] of q.chf.entries()){const p=q.profile[i].p,expected=.795*(1-r.x)**(.105*p-.5)*m.massFlux**(.184-.311*r.x)*(1-.0185*p),check=reactorCheck('chf-current','equation-residual',r.qCritical,expected,1e-10,1e-10,'MW/m²',REACTOR_CHECK_SOURCES.chf,'Eq. 53, p MPa; G kg/(m² s); output MW/m²',`z=${N(r.z)} m; p=${N(p)} MPa; G=${N(m.massFlux)} kg/(m² s); x=${N(r.x)}`);if(reactorWorse(worst,check))worst=check;}rows.push(worst);}
 if(q.neutronics)for(const [state,n] of [['hot',q.neutronics.hot],['cold',q.neutronics.cold]])add(state+'-keff','equation-residual',n.keff,(n.kinfThermal+n.kinfResonance)*Math.exp(-n.Bsq*n.age)/(1+n.Bsq*n.Lsq),1e-12,1e-10,'–',REACTOR_CHECK_SOURCES.guide+' §4.4–4.5','k=(k∞T+k∞R) exp(−B²τ)/(1+B²L²)',`(${N(n.kinfThermal)} + ${N(n.kinfResonance)}) exp(−${N(n.Bsq)} × ${N(n.age)}) / (1 + ${N(n.Bsq)} × ${N(n.Lsq)})`);
 return {version:REACTOR_EVIDENCE_VERSION,status:rows.every(r=>r.status==='passed')?'passed':'failed',checks:rows};
}
function reactorVerificationTables(q,en=false){
 const t=(uk,eng)=>en?eng:uk,current=reactorCalculationChecks(q),ref=reactorReferenceChecks(),label=s=>({passed:t('У допуску','Within tolerance'),failed:t('Поза допуском','Outside tolerance'),unavailable:t('Немає результату','Unavailable')})[s];
 const kinds={balance:t('Баланс рівнянь','Equation balance'),'equation-residual':t('Нев’язка рівняння','Equation residual'),analytical:t('Аналітичний приклад','Analytical case'),'correlation-arithmetic':t('Арифметика кореляції','Correlation arithmetic'),'physical-screening':t('Експериментальний еталон','Experimental reference'),'reconstructed-screening':t('Реконструйована комірка','Reconstructed cell')};
 const make=(title,rows)=>({className:'reactor-verification',title,headers:[t('Приклад / рівняння','Case / equation'),t('Тип перевірки','Check type'),t('Отримано','Actual'),t('Еталон / права частина','Reference / RHS'),t('Допуск |Δ|','Tolerance |Δ|'),t('Відхилення |Δ|','Error |Δ|'),t('Статус','Status'),t('Одиниця','Unit'),t('Джерело','Source')],rows:rows.map(r=>[r.id,kinds[r.kind],r.actual,r.expected,r.tolerance,r.absoluteError,label(r.status),r.unit,r.source])});
 return [make(t('Перевірка рівнянь поточного розрахунку','Current calculation equation checks'),current.checks),make(t('Контрольні приклади: арифметика та експеримент окремо','Reference cases: arithmetic and experiment separately'),ref.checks),{className:'reactor-verification',title:t('Формули й числові підстановки перевірок','Check formulas and numerical substitutions'),headers:[t('Перевірка','Check'),t('Формула','Formula'),t('Підстановка','Substitution'),t('Джерело','Source')],rows:[...current.checks,...ref.checks].map(r=>[r.id,r.formula,r.substitution,r.source])}];
}


// src/reactor-course-tables.js
function reactorNodeSteps(q,index){const r=q.profile[index];if(!r)throw Error('Unknown reactor node');const a=q.input,g=q.geometry;
 const f=(key,uk,en,formula,value,unit,sub)=>reactorStep(key,uk,en,formula,value,unit,sub),N=x=>Number(x.toPrecision(8)).toString();
 return [f('qLinear','Лінійний потік','Linear heat rate','q′(z) = q′max cos(βz)',r.qLinear,'kW/m',`${N(q.metrics.peakLinear)} cos(${N(q.metrics.beta)} × ${N(r.z)})`),f('Re','Reynolds','Reynolds','Re = w dг/(μv)',r.Re,'–',`${N(r.velocity)} × ${N(g.dhyd)} / (${N(r.mu)} × ${N(r.v)})`),f('alpha','Тепловіддача','Heat transfer','αкон = (0,026 S/d−0,006)λ/dг Re⁰·⁸Pr¹/³',r.alphaConv,'W/(m² K)',`(0.026 × ${a.pitchRatio} − 0.006) × ${N(r.lambda)} / ${N(g.dhyd)} × ${N(r.Re)}^0.8 × ${N(r.Pr)}^(1/3)`),f('cladOuter','Оболонка зовні','Outer cladding',r.boiling?'tзовн = tнас+(Kαqпов−qпоч)/√(αкон²+αкип²)':'tзовн = tводи+Kαq′/(πdαкон)',r.cladOuter,'°C',r.boiling?`${N(r.saturationC)} + ${N(r.excessFlux*1e6)} / ${N(r.alpha)}`:`${N(r.t)} + ${a.heatFactor} × ${N(r.qLinear*1000)} / (π × ${N(g.d)} × ${N(r.alphaConv)})`),f('cladInner','Оболонка всередині','Inner cladding','tвн = tзовн+Kλq′ ln(d/dᵢ)/(2πλоб)',r.cladInner,'°C',`${N(r.cladOuter)} + ${a.conductionFactor} × ${N(r.qLinear*1000)} × ln(${N(g.d)}/${N(g.di)}) / (2π × ${N(r.cladLambda)})`),f('fuelSurface','Поверхня палива','Fuel surface',a.gapMethod==='contact'?'tпов = tвн+Kλq′/(πdпалαконт)':a.gapMethod==='perfect'?'tпов = tвн':'tпов = tвн+Kλq′ ln(dᵢ/dпал)/(2πλгаз)',r.fuelSurface,'°C',`Δt = ${N(r.fuelSurface-r.cladInner)} K; λгаз = ${r.gapLambda===null?'—':N(r.gapLambda)}`),f('fuelCenter',g.hole>0?'Поверхня центрального отвору':'Центр таблетки',g.hole>0?'Inner bore surface':'Pellet centre','tmax = tпов+Kλq′[1+2χ²lnχ/(1−χ²)]/(4πλUO₂)',r.fuelCenter,'°C',`χ = ${N(g.hole/g.df)}; λUO₂ = ${N(r.fuelLambda)}; Δt = ${N(r.fuelCenter-r.fuelSurface)}`)];}
function reactorCourseTables(q,en=false){const headers=en?['Quantity','Formula','Substitution','Result','Unit']:['Величина','Формула','Підстановка','Результат','Одиниця'],steps=list=>({headers,rows:list.map(s=>[s.label[en?1:0],s.formula,s.substitution,s.value,s.unit])}),profile=(list)=>({headers:['z [m]','p [MPa abs]','q′ [kW/m]','h [kJ/kg]','t [°C]','v [m³/kg]','w [m/s]','μ [Pa s]','λ [W/(m K)]','Pr','Re','α [W/(m² K)]','t sat [°C]','t clad out [°C]','t clad in [°C]','t fuel surface [°C]','t fuel max [°C]'],rows:list.map(r=>['z','p','qLinear','h','t','v','velocity','mu','lambda','Pr','Re','alpha','saturationC','cladOuter','cladInner','fuelSurface','fuelCenter'].map(k=>r[k]))});
 const tables=[steps(q.steps),steps(reactorNodeSteps(q,Math.floor(q.profile.length/2))),profile(q.profile),profile(q.controlProfile)];
 if(q.chf)tables.push({headers:['z [m]','x eq','m','n','q critical [MW/m²]','q actual [MW/m²]','CHF/q (review applicability)'],rows:q.chf.map(r=>Object.values(r))});
 if(q.neutronics){const n=q.neutronics;tables.push({headers:en?['Age [reloads]','Assemblies','UO₂ [kg]','Initial U-235 [kg]','Consumed U-235 [kg]','U-235 [kg]','U-238 [kg]','Enrichment [% atom]']:['Вік [перевантажень]','Касет','UO₂ [кг]','Початковий U-235 [кг]','Витрачено U-235 [кг]','U-235 [кг]','U-238 [кг]','Збагачення [% атом]'],rows:n.zones.zones.map(r=>Object.values(r))},steps(q.neutronSteps),{headers:['t [day]','Z','N U-235 [cm⁻³]','N Pu-239 [cm⁻³]','N Xe-135 [cm⁻³]','N Sm [cm⁻³]','N slag [cm⁻³]','Σa fuel [cm⁻¹]','k∞ raw','k_eff estimate'],rows:n.campaign.profile.map(r=>Object.values(r))});
 tables.push({headers:en?['Neutron quantity','Hot','Cold']:['Нейтронна величина','Гарячий стан','Холодний стан'],rows:['rhoWater','Nwater','Tng','sa5','sa8','sf5','saZr','saWater','str0','str1','mu','nuEff','phi','boundaryGamma','theta','kinf','Lsq','age','Bsq','keff'].map(k=>[k,n.hot[k],n.cold[k]])});}
 const names=[en?"3.1–3.6 Geometry, thermal calculation and hydraulics":"3.1–3.6 Геометрія, тепловий розрахунок і гідравліка",en?"3.3 Formula substitutions at the selected axial node":"3.3 Підстановки для вибраного перетину",en?"3.3 Detailed axial profile":"3.3 Докладний осьовий профіль",en?"3.3 Seven control sections":"3.3 Сім контрольних перетинів",...(q.chf?[en?"3.4 Critical heat flux margin":"3.4 Запас до кризи теплообміну"]:[]),en?"4.1 Fuel reload zones":"4.1 Зони перевантаження палива",en?"4.2–4.8 Experimental neutron model":"4.2–4.8 Дослідна нейтронна модель",en?"4.6 Estimated campaign":"4.6 Оцінка кампанії",en?"Hot and cold neutron states":"Гарячий і холодний нейтронні стани"];tables.forEach((t,i)=>t.title=names[i]);
 if(q.neutronics)tables.push({title:en?'6. Rod layout and individual contributions':'6. Картограма стрижнів та окремі внески',headers:['r [m]','assemblies','rods','2.405 r/R_eff','J₀²','Δk before interference'],rows:q.neutronics.controls.rings.map(r=>[r.radius,r.assemblies,r.rods,r.argument,r.weight,r.rods*r.weight*q.neutronics.controls.centralWorth])});
 if(q.neutronics)tables.push({title:en?'6–7. Rod count search within the specified layout (inner radii first)':'6–7. Пошук кількості касет у заданій схемі (від центра)',headers:['assemblies','Δk rods','g B/kg H₂O','g H₃BO₃/kg H₂O'],rows:q.neutronics.controlStudy.rows.map(r=>[r.assemblies,r.rodWorth,r.boron,r.boricAcid])});
 tables.push({title:en?'3.3 Subcooled boiling calculation':'3.3 Розрахунок поверхневого кипіння',headers:['z [m]','α conv [W/(m² K)]','Kα q [MW/m²]','q onset [MW/m²]','q excess [MW/m²]','α boil [W/(m² K)]','α total [W/(m² K)]','wall conv [°C]','wall used [°C]','correction active'],rows:q.controlProfile.map(r=>[r.z,r.alphaConv,r.designFlux,r.onsetFlux,r.excessFlux,r.alphaBoiling,r.alpha,r.convectiveWall,r.cladOuter,r.boiling?1:0])});
 tables.push({title:en?'Guide section coverage':'Охоплення розділів методички',headers:en?['Section','Task','Status']:['Розділ','Задача','Статус'],rows:reactorCoverage(q).map(([code,uk,eng,status])=>[code,en?eng:uk,reactorCoverageLabel(status,en)])});
 tables.push({className:"thermal-evidence",title:en?"Thermal assumptions and source evidence":"Теплові припущення та підтвердження джерелами",headers:en?["Topic","Method","Calculated / specified","Evidence and limits","Source"]:["Розділ","Метод","Розраховано / задано","Підтвердження й межі","Джерело"],rows:reactorThermalEvidence(q,en)});tables.push(...reactorVerificationTables(q,en));return tables;
}

function reactorCampaignSVG(q,en=false){
 if(!q.neutronics)return '';const rows=q.neutronics.campaign.profile,values=rows.map(r=>r.keff).concat(q.input.campaignTarget),low=Math.min(...values),high=Math.max(...values),span=high-low||1,X=t=>70+660*t/q.input.campaignMaxDays,Y=k=>280-210*(k-low)/span;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 350" role="img" aria-label="${en?'Experimental campaign k_eff':'Дослідна оцінка kеф кампанії'}"><g font-family="Arial" font-size="14"><path d="M70 60V280H740" fill="none" stroke="#666"/><text x="70" y="25">${en?'Experimental campaign k_eff':'Дослідна оцінка kеф кампанії'}</text><text x="400" y="330">t [day]</text><text x="10" y="65">${high.toPrecision(5)}</text><text x="10" y="280">${low.toPrecision(5)}</text><text x="70" y="305">0</text><text x="680" y="305">${q.input.campaignMaxDays}</text><path d="M70 ${Y(q.input.campaignTarget)}H730" fill="none" stroke="#b91c1c" stroke-dasharray="5 4"/><polyline points="${rows.map(r=>X(r.days)+','+Y(r.keff)).join(' ')}" fill="none" stroke="#125a88" stroke-width="2"/></g></svg>`;
}
function reactorReportSummary(q,en=false){
 const t=(uk,enText)=>en?enText:uk,N=v=>Number(v.toPrecision(8)),m=q.metrics,checked=reactorCalculationChecks(q);
 return `<aside><h3>${t('Статус записки: у розробці — розрахунок для перевірки','Report status: in development — calculation draft')}</h3><p>${t('Теплові властивості обчислено за обраним ядром. Нейтронна частина дослідна. CHF і поверхневе кипіння обчислюються за обраними кореляціями; резонансний інтеграл — розрахований або заданий; розташування стрижнів — за обраною схемою. Статус кожного розділу наведено окремо. Фізична застосовність наближень, квадратна гранична поправка та контрольний приклад усієї курсової ще потребують звірки.','Water properties use the selected engine. Neutronics is experimental. CHF and subcooled boiling use selected correlations; the resonance integral is calculated or specified; rod layout uses the selected method. Each section has an explicit status. Physical applicability, the square boundary correction and the full coursework reference example still need verification.')}</p><p>${t('Контроль рівнянь поточного розрахунку: ','Current equation checks: ')}${checked.status==='passed'?t('у допуску.','within tolerance.'):t('є розбіжності.','discrepancies found.')} ${t('Експериментальні нейтронні еталони моделі не пройдені. Контрольні приклади та числові допуски наведено нижче окремо від фізичної перевірки.','The model fails experimental neutron screening. Reference cases and numerical tolerances are listed below separately from physical validation.')}</p></aside><h3>${t('Мета та послідовність розрахунку','Objective and calculation sequence')}</h3><p>${t('За геометрією варіанта й електричною потужністю визначаються теплова потужність, витрата теплоносія та розміри активної зони. Для гарячого каналу розраховуються сім контрольних перетинів і докладний осьовий профіль. Температури шарів знаходяться з урахуванням їх теплопровідності. Окремий середній канал забезпечує вхідні температури для нейтронної моделі.','Variant geometry and electrical power determine thermal power, coolant flow and core dimensions. The hot channel is evaluated at seven control sections and on a detailed axial grid. Layer temperatures use their conductivities. A separate mean channel supplies temperatures for the neutron model.')}</p><h3>${t('Висновки за фактичними результатами','Conclusions from calculated values')}</h3><p>Q = ${N(m.thermalMW)} MW; G = ${N(m.flow)} kg/s; H = ${N(m.height)} m; D = ${N(m.diameter)} m.</p><p>${t('Максимальна зовнішня температура оболонки','Maximum outer cladding temperature')}: ${N(m.maxCladOuter)} °C; ${t('задана межа','specified limit')}: ${q.input.cladLimit} °C. ${t('Максимальна температура палива','Maximum fuel temperature')}: ${N(m.maxFuelCenter)} °C; ${t('задана межа','specified limit')}: ${q.input.fuelLimit} °C.</p><p>${t('Розрахований перепад тиску','Calculated pressure drop')}: ${N(m.calculatedDrop)} MPa; ${t('заданий','specified')}: ${q.input.pressureDrop} MPa. ${t('Ці перевірки стосуються заданої навчальної моделі; вони не є оцінкою безпечності реактора.','These checks apply to the specified course model; they are not a reactor safety assessment.')}</p>`;
}

function reactorCHFSVG(q,en=false){
 if(!q.chf)return '';const rows=q.chf,hi=Math.max(q.input.chfLimit,...rows.map(r=>r.ratio))*1.05,X=z=>70+660*(z/q.metrics.height+.5),Y=v=>280-220*v/hi;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 350" role="img" aria-label="CHF/q"><g font-family="Arial" font-size="14"><text x="70" y="25">${en?'CHF/q — correlation applicability requires review':'CHF/q — застосовність кореляції потребує звірки'}</text><path d="M70 50V280H740" fill="none" stroke="#666"/><text x="5" y="65">${hi.toPrecision(4)}</text><text x="45" y="280">0</text><text x="365" y="330">z [m]</text><text x="70" y="305">${rows[0].z.toPrecision(4)}</text><text x="680" y="305">${rows.at(-1).z.toPrecision(4)}</text><path d="M70 ${Y(q.input.chfLimit)}H730" fill="none" stroke="#b91c1c" stroke-dasharray="5 4"/><polyline points="${rows.map(r=>X(r.z)+','+Y(r.ratio)).join(' ')}" fill="none" stroke="#125a88" stroke-width="2"/></g></svg>`;
}
function reactorLayoutSVG(q,en=false){
 if(!q.neutronics)return '';const rows=q.neutronics.controls.rings,R=q.metrics.diameter/2,scale=165/R,cx=235,cy=225,coordinate=q.input.rodLayout==='coordinates';
 const marks=rows.map(r=>coordinate?`<circle cx="${cx+r.x*scale}" cy="${cy-r.y*scale}" r="4" fill="#125a88"/>`:`<circle cx="${cx}" cy="${cy}" r="${r.radius*scale||3}" fill="none" stroke="#125a88"/>`).join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 440" role="img" aria-label="${en?'Specified rod layout':'Задана схема стрижнів'}"><g font-family="Arial" font-size="14"><text x="60" y="25">${en?'Specified rod layout (assembly centres)':'Задана схема стрижнів (центри касет)'}</text><circle cx="${cx}" cy="${cy}" r="165" fill="none" stroke="#666"/><path d="M70 225H400M235 60V390" stroke="#ccc"/>${marks}<text x="460" y="90">R = ${R.toPrecision(6)} m</text><text x="460" y="120">${en?'Assemblies':'Касет'}: ${q.input.controlAssemblies}</text><text x="460" y="150">${en?'Rods per assembly':'ПЕЛів у касеті'}: ${q.input.rodsPerCluster}</text><text x="460" y="180">Δk = ${q.neutronics.controls.totalWorth.toPrecision(6)}</text><text x="60" y="420">${coordinate?(en?'Coordinates supplied by user':'Координати задано користувачем'):(en?'Circles show radii; angular positions are not specified':'Кола показують радіуси; кутові положення не задані')}</text></g></svg>`;
}


