// src/print-report.js
function printableReport(title,states,system='si',energy='kJ',context={}){
 const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fields=[['p','MPa'],['T','K'],['h','kJ/kg'],['s','kJ/(kg K)'],['u','kJ/kg'],['rho','kg/m3'],['v','m3/kg'],['cp','kJ/(kg K)'],['cv','kJ/(kg K)'],['w','m/s'],['x','-']];
 const pressure=context.pressure||{basis:'absolute',atmosphere:.101325};
 const convert=(k,v,u)=>{if(k==='p'&&v!=null&&pressure.basis==='gauge')v-=pressure.atmosphere;const out=system==='english'?englishProperty(k,v,u):energy==='J'&&['h','s','u','ex','cp','cv'].includes(k)?[v==null?null:v*1000,u.replace('kJ','J')]:[v,u];const transport=uiTransportQuantity(k,...out,context.preferences);return [transport[0],transport[1]+(k==='p'&&pressure.basis==='gauge'?' (gauge)':'')];};
 const number=v=>Number.isFinite(v)?esc(Number(v.toPrecision(10))):'—';
 const cell=(k,v,u)=>number(convert(k,v,u)[0]);
 const notes=list=>[...new Set(list||[])].map(n=>`<p>${esc(n)}</p>`).join('');
 const source=q=>q.source?`<p><strong>Задано:</strong> ${esc(q.source.mode.toUpperCase())}; a = ${number(q.source.a)}; b = ${number(q.source.b)} (канонічні SI: MPa (абсолютний тиск), K, kJ/kg, kJ/(kg K), m³/kg, kg/m³, частка 0…1 відповідно до режиму).</p><p>${esc(modeGuidance(q.source.mode))}</p>`:'';
 const r=context.result;
 let current='';
 if(r){
  const list=r.state?[['Поточний стан',r.state]]:r.saturation?[['Насичена рідина',r.saturation.liquid],['Насичена пара',r.saturation.vapor]]:[];
  const extraFields=[['ex','kJ/kg'],['mu','Pa s'],['lambda','W/(m K)'],['nu','m2/s'],['Pr','-'],['sigma','N/m']];
  current='<h2>Поточний стан і пояснення</h2>'+list.map(([label,q])=>`<h3>${esc(label)} · ${esc(q.model||'IF97')} · ${esc(q.phase)}</h3>${source(q)}<table class="properties"><thead><tr><th>Властивість</th><th>Результат</th><th>Одиниця</th></tr></thead><tbody>${[...fields,...extraFields].map(([k,u])=>`<tr><td>${k}</td><td>${cell(k,q[k],u)}</td><td>${esc(convert(k,null,u)[1])}</td></tr>`).join('')}</tbody></table>${notes(q.notes)}`).join('');
  if(r.ambiguous)current+='<p>P–T на насиченні не визначає сухість. Для суміші задайте P–x, T–x або інший незалежний параметр.</p>';
  current+='<p>Співвідношення в канонічних SI: ρ = 1/v; u = h − 1000·p·v (p — абсолютний тиск у MPa, v у m³/kg, h та u у kJ/kg).</p>';
  if(r.state?.x!=null&&r.state.x>0&&r.state.x<1)current+='<p>Для рівноважної суміші h, s, u, v = (1−x)·значення рідини + x·значення пари. Густина дорівнює 1/v; теплоємності та транспортні властивості суміші не усереднюються.</p>';
  if(context.ambient)current+=`<p>Фізична ексергія потоку: ex = (h−h₀)−T₀(s−s₀). Довкілля: P₀ = ${number(context.ambient.p)} MPa; T₀ = ${number(context.ambient.T)} K. Без хімічної, кінетичної та потенціальної складових.</p>`;
 }
 const journal=states.length?`<h2>Порівняння станів</h2><table><thead><tr><th>Стан</th>${fields.map(([k,u])=>`<th>${k} [${esc(convert(k,null,u)[1])}]</th>`).join('')}<th>Модель</th><th>Фаза</th></tr></thead><tbody>${states.map(q=>`<tr><td ${q.name?'data-i18n-ignore':''}>${esc(q.name||'Стан')}</td>${fields.map(([k,u])=>`<td>${cell(k,q[k],u)}</td>`).join('')}<td>${esc(q.model||'IF97')}</td><td>${esc(q.phase)}</td></tr>`).join('')}</tbody></table>`:'';
 // extra is generated from the current application DOM, never read from imported files.
 return `<!doctype html><html lang="uk"><meta charset="utf-8"><title data-i18n-ignore>${esc(title)} · звіт</title><style>body{font:14px Arial;margin:24px;color:#182b40}table{border-collapse:collapse;width:100%;font-size:11px}td,th{border:1px solid #abc;padding:6px;text-align:right}th:first-child,td:first-child{text-align:left}thead{display:table-header-group}tr{break-inside:avoid}h2,h3{break-after:avoid}.properties{max-width:650px}svg{max-width:100%;height:auto}button,form,input,select,textarea{display:none}@page{size:A4 landscape;margin:12mm}@media print{body{margin:0}}</style><h1 data-i18n-ignore>${esc(title)}</h1><p>Тиск водяних таблиць: ${pressure.basis==='gauge'?'Манометричний тиск; Pатм = '+number(pressure.atmosphere)+' MPa (абс.)':'Абсолютний тиск'} · ${system==='english'?'Англійські одиниці, Btu IT':'SI'} · модель зазначена для кожного розрахунку.</p>${context.extra||''}${current}${journal}<p>Позначення: p — тиск; T — температура; h — ентальпія; s — ентропія; u — внутрішня енергія; ρ — густина; v — питомий об’єм; x — масова частка пари. Невизначені величини позначено —. Числова точність відображення не є оцінкою фізичної невизначеності.</p></html>`;
}


// src/export.js
// Unrounded canonical values; energy unit is explicitly recorded in each CSV row.
function resultExportRows(result,energy='kJ',ambient=null,system='si',preferences=null) {
  const props=[['dc','–'],['ex','кДж/кг'],['h','кДж/кг'],['s','кДж/(кг·K)'],['rho','кг/м³'],['v','м³/кг'],['cp','кДж/(кг·K)'],['cv','кДж/(кг·K)'],['w','м/с'],['u','кДж/кг'],['mu','Па·с'],['lambda','Вт/(м·K)'],['A','кДж/кг'],['G','кДж/кг'],['Z','–'],['isentropic','–'],['alpha','1/K'],['kappa','1/МПа'],['dvdt','м³/(кг·K)'],['dvdp','м³/(кг·МПа)'],['dpdt','МПа/K'],['dpdv','МПа·кг/м³'],['jt','K/МПа'],['ijt','кДж/(кг·МПа)'],['nu','м²/с'],['diffusivity','м²/с'],['Pr','–'],['sigma','Н/м']];
  const rows=[['state','property','value','unit'],['reference','pressure_basis','absolute','']],states=result.state?[['state',result.state]]:[];
  if(ambient)rows.push(['reference','p0',ambient.p,'MPa'],['reference','T0',ambient.T,'K'],['reference','exergy_definition','(h-h0)-T0*(s-s0); physical flow exergy','']);
  if(result.saturation)states.push(['saturated_liquid',result.saturation.liquid],['saturated_vapor',result.saturation.vapor]);
  if(result.alternatives)result.alternatives.forEach((s,i)=>states.push(['alternative_'+(i+1),s]));
  for(const [name,s] of states) {
    rows.push([name,'p',...(system==='english'?englishProperty('p',s.p,'MPa'):[s.p,'MPa'])],[name,'T',...(system==='english'?englishProperty('T',s.T,'K'):[s.T,'K'])],[name,'model',s.model||'IF97',''],[name,'region',s.region??'',''],[name,'phase',s.phase,''],[name,'x',s.x??'','']);
    for(const [key,unit] of props) {
      if(s[key]==null&&['mu','nu','lambda','diffusivity','Pr','dc','sigma'].includes(key))rows.push([name,key+'_unavailable_reason',propertyUnavailableReason(key,s),'']);
      if(system==='english'){const [v,u]=uiTransportQuantity(key,...englishProperty(key,s[key],unit),preferences);rows.push([name,key,v??'',u]);continue;}const convert=energy==='J'&&['h','s','cp','cv','u','A','G','ijt','ex'].includes(key);const [v,u]=uiTransportQuantity(key,s[key],convert?unit.replace('кДж','Дж'):unit,preferences);rows.push([name,key,v==null?'':v*(convert?1000:1),u]);}
    if(s.inputSensitivity){rows.push([name,'rounding_response_status',s.inputSensitivity.status,'']);for(const [key,value] of Object.entries(s.inputSensitivity.response||{}))rows.push([name,'rounding_response_'+key,value,DIAGNOSTIC_UNITS[key]]);for(const [key,value] of Object.entries(s.inputSensitivity.numericalResponse||{}))rows.push([name,'numerical_response_'+key,value,DIAGNOSTIC_UNITS[key]]);}
    for(const note of s.notes||[])rows.push([name,'note',note,'']);
  }
  if(result.diagnostics){const d=result.diagnostics;rows.push(['diagnostics','root_selection',d.selection,''],['diagnostics','numerical_duplicates_merged',d.merged,'']);if(d.roundingScenario){rows.push(['diagnostics','rounding_assumption',d.roundingScenario.assumption,'']);for(const x of d.roundingScenario.inputs)rows.push(['diagnostics','input_half_step_'+x.key,x.halfWidth,x.unit]);}}
 return rows;
}

function exportCSV(result,energy='kJ',ambient=null,system='si',preferences=null){
 const rows=resultExportRows(result,energy,ambient,system,preferences);
 return '\uFEFF'+rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');
}


// src/tabular-data.js

// A typed document shared by every writer. No display rounding or CSV parsing.
function tabularDocument(kind,tables,context={}){
 const metadata={...context,format:'water-steam-tabular',schema:1,kind,pressure_basis:'absolute'};
 const metaRows=[['key','value'],...Object.entries(metadata).map(([k,v])=>[k,v??null]),['blank_value','Unavailable or inapplicable; never a numeric zero.'],['precision','Unrounded JavaScript binary64; spreadsheet readers may display fewer digits.']];
 const all=[{name:'Metadata',rows:metaRows},...tables];
 if(all.length>20||!tables.length)throw Error('Invalid spreadsheet tables.');
 const names=new Set();
 const sheets=all.map(({name,rows})=>{
  if(typeof name!=='string'||!name||name.length>31||/[\\/?*\[\]:]/.test(name)||names.has(name.toLowerCase()))throw Error('Invalid or duplicate worksheet name.');
  names.add(name.toLowerCase());
  // Common limits keep XLS, XLSX and ODS exports equivalent and prevent truncation.
  if(!Array.isArray(rows)||rows.length>65536)throw Error('Worksheet exceeds the Excel 97–2003 row limit.');
  return {name,rows:rows.map(row=>{
   if(!Array.isArray(row)||row.length>256)throw Error('Worksheet exceeds the Excel 97–2003 column limit.');
   return row.map(value=>{
    if(value==null)return null;
    if(typeof value==='number'){if(!Number.isFinite(value))throw Error('Non-finite spreadsheet value.');return value;}
    if(typeof value==='boolean')return value;
    if(typeof value!=='string'||value.length>32767)throw Error('Invalid spreadsheet text.');
    return value;
   });
  })};
 });
 return {format:'water-steam-tabular',version:1,sheets};
}

function completeStateRows(result,energy,ambient,system,preferences){
 const records=resultExportRows(result,energy,ambient,system,preferences);
 const states=[...(result.state?[['state',result.state]]:[]),...(result.saturation?[['saturated_liquid',result.saturation.liquid],['saturated_vapor',result.saturation.vapor]]:[]),...(result.alternatives||[]).map((q,i)=>['alternative_'+(i+1),q])];
 for(const [name,state] of states){
  for(const row of records.filter(r=>r[0]===name)){
   const key=row[1];
   if(row[2]===''&&(state[key]===null||state[key]===undefined)&&!key.endsWith('_unavailable_reason')){
    row[2]=null;
    if(!records.some(r=>r[0]===name&&r[1]===key+'_unavailable_reason'))records.push([name,key+'_unavailable_reason',propertyUnavailableReason(key,state),'']);
   }
  }
 }
 return records;
}
function resultTabular(result,context={}){
 if(!result?.state&&!result?.saturation)throw Error('Calculate a state before exporting.');
 const {system='si',energy='kJ',p0=.101325,T0=298.15}=context;
 return tabularDocument('state',[{name:'Properties',rows:completeStateRows(result,energy,{p:p0,T:T0},system,context)}],context);
}
function historyTabular(states,context={}){
 if(!states.length)throw Error('No calculated history to export.');
 const rows=[['name','state','property','value','unit']];
 for(const q of states)rows.push(...completeStateRows({state:q},context.energy||'kJ',null,context.system||'si',context).slice(1).map(r=>[q.name||'',...r]));
 return tabularDocument('history',[{name:'Properties',rows}],{...context,model:'per result'});
}
function saturationTabular(records,model,context={}){
 if(!records.length)throw Error('Generate a saturation table before exporting.');
 const cell=(k,q)=>saturationCell(k,q,context.system||'si',context.energy||'kJ');
 const rows=[['input ['+(context.input_unit||'?')+']',...SATURATION_COLUMNS.map(([k,label])=>label+' ['+cell(k,null)[1]+']'),'status','message'],...records.map(r=>[r.input,...SATURATION_COLUMNS.map(([k])=>r.error?null:cell(k,r.saturation)[0]),r.error?'error':'ok',r.error||''])];
 return tabularDocument('saturation',[{name:'Saturation',rows}],{...context,model});
}
function processTabular(kind,result,context={}){
 const states=[result.inlet,...(result.ideal?[result.ideal]:[]),result.outlet];
 return tabularDocument(kind,[{name:'Process',rows:processExportRows(kind,result,context.system||'si')},{name:'Properties',rows:[['point','state','property','value','unit'],...states.flatMap((q,i)=>completeStateRows({state:q},'kJ',null,context.system||'si',context).slice(1).map(row=>[i+1,...row]))]}],{...context,model:result.inlet.model||'IF97'});
}
function diagramTabular(entries,plan={},context={},preferences){
 if(!entries.length)throw Error('No calculated diagram points to export.');
 return tabularDocument('diagram',[{name:'Points and series',rows:diagramExportRows(entries,context.system||'si',context.energy||'kJ',plan,preferences)},{name:'Properties',rows:[['name','state','property','value','unit'],...entries.flatMap(([q,name])=>completeStateRows({state:q},context.energy||'kJ',null,context.system||'si',context).slice(1).map(row=>[name,...row]))]}],context);
}
function batchTabular(records,context={}){
 if(!records.length)throw Error('Calculate a batch before exporting.');
 const states=records.filter(r=>!r.error).flatMap(r=>batchStates(r).map(q=>({...q,name:r.input.name})));
 const rows=[['name','status','message'],...records.map(r=>[r.input.name,r.error?'error':'ok',r.error||''])];
 const properties=[['name','state','property','value','unit'],...states.flatMap(q=>completeStateRows({state:q},context.energy||'kJ',null,context.system||'si',context).slice(1).map(row=>[q.name,...row]))];
 return tabularDocument('batch',[{name:'Batch',rows},{name:'Properties',rows:properties}],context);
}

function gasTabular(q,inputs={},context={},preferences=null){
 if(!q?.modelId?.startsWith('BSW2003-'))throw Error('Calculate a BSW2003 state before exporting.');
 return tabularDocument('gas',[{name:'Properties',rows:[['property','value','unit'],...gasTableRows(q,context.system||'si',preferences)]},{name:'Composition',rows:[['component','mole [%]','mass [%]'],...gasCompositionRows(q)]},{name:'Inputs',rows:[['field','value'],...Object.entries(inputs)]}],{...context,model:q.model,composition_basis:q.inputBasis,T0_K:q.reference.T0,p0_MPa:q.reference.p0,reference:q.reference.definition,dissociation_applied:q.dissociationApplied,...(q.dissociationApplied?{dissociation_model:q.dissociation.model,excess_air_lambda:q.excessAirLambda,combustion:q.dissociation.combustion,composition_meaning:q.compositionMeaning,equilibrium_composition_computed:false,sound_speed_available:false,Steam97Web_parity_verified:false,cp_definition:q.dissociation.cpDefinition}:{})});
}


// src/spreadsheet.js

const SPREADSHEET_FORMATS={xlsx:{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',bookType:'xlsx'},ods:{type:'application/vnd.oasis.opendocument.spreadsheet',bookType:'ods'},xls:{type:'application/vnd.ms-excel',bookType:'biff8'},csv:{type:'text/csv;charset=utf-8'}};
const spreadsheetCRCTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0;});
function spreadsheetStoredODF(bytes){
 // Repackage only our own freshly generated archive. SheetJS puts mimetype
 // third; ODF 1.2 §3.3 requires it first, stored and without an extra field.
 const archive=SheetJS.CFB.read(bytes,{type:'array'}),root=archive.FullPaths[0];
 const entries=archive.FileIndex.flatMap((entry,i)=>entry.type===2&&!entry.name.startsWith('\x01')?[{name:archive.FullPaths[i].slice(root.length),data:new Uint8Array(entry.content)}]:[]);
 entries.sort((a,b)=>a.name==='mimetype'?-1:b.name==='mimetype'?1:0);
 if(entries[0]?.name!=='mimetype')throw Error('Invalid generated ODF archive.');
 const encoder=new TextEncoder(),locals=[],central=[];let offset=0;
 for(const entry of entries){
  const name=encoder.encode(entry.name),data=entry.data;let crc=0xffffffff;for(const b of data)crc=spreadsheetCRCTable[(crc^b)&255]^(crc>>>8);crc=(crc^0xffffffff)>>>0;
  const local=new Uint8Array(30+name.length),lv=new DataView(local.buffer);
  lv.setUint32(0,0x04034b50,true);lv.setUint16(4,20,true);lv.setUint16(6,0x800,true);lv.setUint16(12,33,true);lv.setUint32(14,crc,true);lv.setUint32(18,data.length,true);lv.setUint32(22,data.length,true);lv.setUint16(26,name.length,true);local.set(name,30);
  const c=new Uint8Array(46+name.length),cv=new DataView(c.buffer);
  cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint16(14,33,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);c.set(name,46);
  locals.push(local,data);central.push(c);offset+=local.length+data.length;
 }
 const centralSize=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);
 ev.setUint32(0,0x06054b50,true);ev.setUint16(8,entries.length,true);ev.setUint16(10,entries.length,true);ev.setUint32(12,centralSize,true);ev.setUint32(16,offset,true);
 const output=new Uint8Array(offset+centralSize+22);let pos=0;for(const chunk of [...locals,...central,end]){output.set(chunk,pos);pos+=chunk.length;}return output;
}
function writeTabular(document,format='xlsx'){
 const spec=SPREADSHEET_FORMATS[format];if(!spec)throw Error('Unknown spreadsheet format.');
 if(document?.format!=='water-steam-tabular'||document.version!==1||!document.sheets?.length)throw Error('Invalid tabular document.');
 for(const sheet of document.sheets)for(const row of sheet.rows)for(const v of row)if(v!=null&&!(['string','boolean'].includes(typeof v)||typeof v==='number'&&Number.isFinite(v)))throw Error('Invalid spreadsheet cell.');
 // The vendored BIFF8 writer cannot split a single long Unicode SST value
 // safely across CONTINUE records. Reject before writing, never truncate/hang.
 if(format==='xls'&&document.sheets.some(s=>s.rows.some(r=>r.some(v=>typeof v==='string'&&v.length>4000))))throw Error('Text exceeds the XLS export limit (4000 characters per cell). Choose XLSX or ODS.');
 if(format==='csv'){
  // A single CSV contains all named sections and metadata, with UTF-8 BOM.
  // Protect text against formula interpretation; actual negative numbers stay numeric.
  const cell=v=>'"'+String(typeof v==='string'&&/^[\s\u0000-\u001f]*[=+\-@]/.test(v)?"'"+v:v??'').replaceAll('"','""')+'"';
  return '\ufeff'+document.sheets.flatMap(s=>[['worksheet',s.name],...s.rows,[]]).map(r=>r.map(cell).join(';')).join('\r\n');
 }
 const book=SheetJS.utils.book_new();
 book.Props={Title:'Water and steam calculated results',Author:'water-steam-if97',CreatedDate:new Date('2000-01-01T00:00:00Z'),ModifiedDate:new Date('2000-01-01T00:00:00Z')};
 for(const s of document.sheets){
  // aoa_to_sheet keeps numbers numeric and formula-like strings as string cells.
  const sheet=SheetJS.utils.aoa_to_sheet(s.rows,{sheetStubs:true});
  SheetJS.utils.book_append_sheet(book,sheet,s.name);
 }
 // ODF requires its first mimetype member to be stored, never compressed.
 // BIFF8 needs its shared string table to retain text beyond 255 characters.
 const bytes=new Uint8Array(SheetJS.write(book,{bookType:spec.bookType,type:'array',compression:format!=='ods',bookSST:true}));
 return format==='ods'?spreadsheetStoredODF(bytes):bytes;
}


// src/spreadsheet-ui.js

// One compact format selector beside each existing export; no extra result panel.
function attachSpreadsheetExport(anchor,{id,getDocument,download,onError,translate=x=>x}){
 const group=document.createElement('span');group.className='spreadsheet-export';group.id=id;
 const select=document.createElement('select');select.id=id+'-format';select.setAttribute('aria-label','Формат таблиці');
 for(const [value,text] of [['xlsx','XLSX'],['ods','ODS'],['xls','XLS (97–2003)'],['csv','CSV (UTF-8)']]){const option=document.createElement('option');option.value=value;option.textContent=text;select.append(option);}
 const button=document.createElement('button');button.type='button';button.id=id+'-save';button.dataset.i18n='spreadsheet.save';button.textContent='Зберегти таблицю';
 button.onclick=()=>{try{const format=select.value,doc=getDocument(),content=writeTabular(doc,format);download(content,id+'.'+format,SPREADSHEET_FORMATS[format].type,{metadata:false});}catch(e){onError?.(e);}};
 group.append(select,button);anchor.after(group);return group;
}


// src/result-copy.js
function resultJSON(result,build,reference,units){
 return JSON.stringify({format:'water-steam-result',version:1,build,pressure_basis:'absolute',units,reference,result},null,2);
}
function resultMarkdown(sections,headings){
 const escape=v=>String(v??'—').replaceAll('\\','\\\\').replaceAll('|','\\|').replace(/[\r\n]+/g,' ');
 return sections.map(({title,rows})=>`### ${escape(title)}\n\n| ${headings.map(escape).join(' | ')} |\n| ${headings.map(()=>'---').join(' | ')} |\n`+rows.map(row=>'| '+row.map(escape).join(' | ')+' |').join('\n')).join('\n\n');
}


// src/calculator-result-tools.js
// Clipboard numbers match displayed precision, without thousands separators.
function calculatorCopyValue(value,unit,{digits=8,locale='uk-UA',includeUnit=true}={}){
 if(!Number.isFinite(value))return null;
 const text=new Intl.NumberFormat(locale,{useGrouping:false,maximumSignificantDigits:digits,notation:Math.abs(value)>0&&Math.abs(value)<1e-4?'scientific':'standard'}).format(value);
 return text+(includeUnit&&unit&&unit!=='–'?' '+unit:'');
}
// Restore the recorded input pair; legacy snapshots have no source metadata.
function calculatorHistoryInput(state){
 const s=state.source,pair=SMART_PAIRS[s?.mode];
 if(pair&&Number.isFinite(s.a)&&(pair[1]==='sat'||Number.isFinite(s.b)))return {mode:s.mode,a:s.a,b:pair[1]==='sat'?0:s.b};
 if(state.critical)return {mode:'pt',a:state.p,b:state.T};
 if(Number.isFinite(state.x)&&state.x>=0&&state.x<=1)return {mode:'px',a:state.p,b:state.x};
 return {mode:'ph',a:state.p,b:state.h};
}


// src/batch.js
function batchUnits(mode){const energy=['kJkg','Jkg','Btulb'],volume=['m3kg','ft3lb'];return {a:['satt','tx','th','ts','trho','tv','tu'].includes(mode)?['C','K','F']:['hs','hv','us','uv'].includes(mode)?energy:mode==='vs'?volume:['MPa','kPa','Pa','bar','atm','psi'],b:['prho','trho'].includes(mode)?['kgm3','lbft3']:['pv','tv','hv','uv'].includes(mode)?volume:['px','tx'].includes(mode)?['fraction','percent']:['ph','th','pu','tu'].includes(mode)?energy:['ps','ts','hs','us','vs'].includes(mode)?['kJkgK','JkgK','BtulbR']:['C','K','F']};}
function batchRange({mode,vary,start,end,count,fixed,ua,ub}){
 if(!['pt','ph','ps','satp','satt','px','tx','hs','th','ts','prho','trho','pv','tv','pu','tu','us','vs','hv','uv'].includes(mode)||!['a','b'].includes(vary))throw Error('Невірний режим серії.');
 if(![start,end,count].every(Number.isFinite)||!Number.isInteger(count)||count<2||count>500)throw Error('Кількість точок має бути цілим числом 2…500.');
 if(!mode.startsWith('sat')&&!Number.isFinite(fixed))throw Error('Введіть фіксований параметр.');
 if(mode.startsWith('sat')&&vary!=='a')throw Error('Для насичення змінюється лише перший параметр.');
 return Array.from({length:count},(_,i)=>({mode,a:vary==='a'?start+(end-start)*i/(count-1):fixed,b:vary==='b'?start+(end-start)*i/(count-1):fixed,ua,ub,name:`Точка ${i+1}`}));
}
function parseBatchCSV(text){
 if(typeof text!=='string'||text.length>1000000)throw Error('CSV має бути не більшим за 1 МБ.');
 text=text.replace(/^\uFEFF/,'');const first=text.split(/\r?\n/)[0];const delimiter=first.includes(';')?';':',';
 const records=[];let fields=[],field='',quoted=false,closed=false;
 for(let i=0;i<=text.length;i++){
 const c=i===text.length?'\n':text[i];
 if(quoted){if(c==='"'){if(text[i+1]==='"'){field+='"';i++;}else{quoted=false;closed=true;}}else field+=c;continue;}
 if(c==='"'){if(field||closed)throw Error('Некоректні лапки CSV.');quoted=true;continue;}
 if(c===delimiter||c==='\n'||c==='\r'){fields.push(field);field='';closed=false;if(c!==delimiter){if(c==='\r'&&text[i+1]==='\n')i++;if(fields.some(v=>v.trim()))records.push(fields);fields=[];}continue;}
 if(closed&&!/\s/.test(c))throw Error('Текст після закритих лапок CSV.');if(!closed)field+=c;
 }
 if(quoted)throw Error('Незакриті лапки CSV.');
 const header=records.shift()?.map(x=>x.trim());const required=['mode','a','b','unit_a','unit_b'];
 if(!header||!required.every(k=>header.includes(k))||new Set(header).size!==header.length||header.some(k=>!required.concat('name').includes(k)))throw Error('Заголовок CSV: mode,a,b,unit_a,unit_b,name (name необов’язково).');
 if(!records.length||records.length>500)throw Error('CSV має містити 1…500 станів.');
 return records.map((r,i)=>{if(r.length!==header.length)throw Error(`Рядок ${i+2}: неправильна кількість стовпців.`);const q=Object.fromEntries(header.map((k,j)=>[k,r[j].trim()]));return {mode:q.mode,a:q.a,b:q.b,ua:q.unit_a,ub:q.unit_b,name:q.name||`CSV ${i+1}`};});
}
function calculateBatch(inputs,model='IF97'){
 if(!Array.isArray(inputs)||inputs.length<1||inputs.length>500)throw Error('Серія має містити 1…500 станів.');
 return inputs.map((input,i)=>{try{
 if(!['pt','ph','ps','satp','satt','px','tx','hs','th','ts','prho','trho','pv','tv','pu','tu','us','vs','hv','uv'].includes(input.mode))throw Error('Невідомий режим.');
 const units=batchUnits(input.mode);if(!units.a.includes(input.ua)||(!input.mode.startsWith('sat')&&!units.b.includes(input.ub)))throw Error('Одиниці не відповідають режиму.');
 const result=calculate(input.mode,toCanonical(parseNumber(input.a),input.ua),input.mode.startsWith('sat')?undefined:toCanonical(parseNumber(input.b),input.ub),model);
 return {input:{...input,name:String(input.name||`Точка ${i+1}`).slice(0,80)},result};
 }catch(e){return {input:{...input,name:String(input.name||`Точка ${i+1}`).slice(0,80)},error:e.message};}});
}
function batchStates(record){return record.result?.state?[record.result.state]:record.result?.saturation?[record.result.saturation.liquid,record.result.saturation.vapor]:[];}
function batchCSV(records,system='si',energy='kJ'){
 const keys=['p','T','h','s','v','rho','cp','cv','w','x','region'];
 const units={p:'MPa',T:'K',h:'kJ/kg',s:'kJ/(kg K)',v:'m3/kg',rho:'kg/m3',cp:'kJ/(kg K)',cv:'kJ/(kg K)',w:'m/s',x:'-',region:'-'};
 const conv=(k,v)=>system==='english'?englishProperty(k,v,units[k]):energy==='J'&&['h','s','cp','cv'].includes(k)?[v==null?null:v*1000,units[k].replace('kJ','J')]:[v,units[k]];
 const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const safe=s=>/^[=+\-@]/.test(s)?"'"+s:s;
 const table=[['name','status',...keys.map(k=>`${k} [${conv(k,null)[1]}]`),'model','phase','message']];
 for(const r of records){if(r.error)table.push([safe(r.input.name),'error',...keys.map(()=>''),'','',safe(r.error)]);else for(const q of batchStates(r))table.push([safe(r.input.name),'ok',...keys.map(k=>conv(k,q[k])[0]),q.model||'IF97',q.phase,(q.notes||[]).join(' | ')]);}
 return '\uFEFF'+table.map(row=>row.map(quote).join(',')).join('\r\n');
}


// src/processes.js
function processSaturation(p,model){
 if(p>=PC)return {T:null,status:'no-saturation'};
 try{return {T:calculate('satp',p,undefined,model).saturation.T,status:'available'};}
 catch{return {T:null,status:'unavailable'};}
}
function processSummary(type,r){
 return type==='turbine'?
  [['work',r.work,'kJ/kg'],['power',r.power,'kW'],['flow',r.flow,'kg/s'],['consumption',r.specificConsumption,'kg/(kW·h)'],['efficiency',r.eta,'fraction'],['inletTsat',r.inletTsat,'K'],['outletSuperheat',r.outletSuperheat,'K']]:
  [['flow',r.flow,'kg/s'],['vaporFlow',r.vaporFlow,'kg/s'],['liquidFlow',r.liquidFlow,'kg/s'],['vaporFraction',r.outlet.x,'fraction']];
}
function processMetricReason(key,r){
 if(key==='inletTsat')return r.inletSaturationStatus==='no-saturation'?'За критичного або надкритичного тиску температура насичення не визначається.':'Температура насичення недоступна за цього тиску в обраній моделі.';
 if(key==='outletSuperheat')return r.outletSuperheatStatus==='compressed-liquid'?'Рідкий вихід: перегрів пари не визначається.':'Перегрів недоступний без температури насичення за вихідного тиску.';
 return 'Вихід однофазний; баланс сепарації на рідину й пару не застосовується.';
}
function processInput(p1,T1,p2,flow,model='IF97'){
 if(![p1,T1,p2,flow].every(Number.isFinite)||flow<0)throw Error('Введіть скінченні числа; витрата не може бути від’ємною.');
 if(p2<=0||p2>=p1)throw Error('Вихідний абсолютний тиск має бути додатним і нижчим за вхідний.');
 const inlet=calculate('pt',p1,T1,model).state;
 if(!inlet)throw Error('На вході потрібен однозначний однофазний стан; P–T на насиченні недостатньо.');
 return inlet;
}
function turbine(p1,T1,p2,eta,flow=1,model='IF97'){
 if(!Number.isFinite(eta)||eta<=0||eta>1)throw Error('Ізоентропний ККД має бути в межах 0 < η ≤ 1.');
 const inlet=processInput(p1,T1,p2,flow,model),ideal=calculate('ps',p2,inlet.s,model).state;
 if(inlet.phase.includes('рідина')||inlet.h<=ideal.h)throw Error('Для парової турбіни задайте паровий стан на вході з додатним перепадом ентальпії.');
 const work=eta*(inlet.h-ideal.h),outlet=calculate('ph',p2,inlet.h-work,model).state;
 if(!(work>0)||!Number.isFinite(flow*work)||!Number.isFinite(3600/work))throw Error('Перепад ентальпії, потужність або питома витрата виходять за числові межі.');
 const sat1=processSaturation(p1,model),sat2=processSaturation(p2,model);
 const outletSuperheat=sat2.T==null?null:outlet.x!=null?0:outlet.T>=sat2.T?outlet.T-sat2.T:null;
 return {inlet,ideal,outlet,work,power:flow*work,eta,flow,specificConsumption:3600/work,inletTsat:sat1.T,outletTsat:sat2.T,outletSuperheat,inletSaturationStatus:sat1.status,outletSuperheatStatus:sat2.T==null?sat2.status:outletSuperheat==null?'compressed-liquid':outlet.x!=null?'saturated':'available'};
}
function flash(p1,T1,p2,flow=1,saturated=0,model='IF97'){
 if(![0,1,2].includes(saturated))throw Error('Невірний режим конденсату.');
 if(![p1,p2,flow].every(Number.isFinite)||flow<0||p2<=0||p2>=p1)throw Error('Перевірте тиски й витрату.');
 const inlet=saturated===1?calculate('px',p1,0,model).state:processInput(p1,T1,p2,flow,model);
 if(saturated===1&&inlet.critical)throw Error('У критичній точці немає окремої насиченої рідини.');
 if(saturated===2&&(inlet.T>=TC||!inlet.phase.includes('рідина')))throw Error('Для недогрітого конденсату потрібна однофазна стиснена рідина на вході.');
 const result=calculate('ph',p2,inlet.h,model),outlet=result.state;
 const x=outlet.x;
 return {inlet,outlet,flow,inletMode:['single-phase','saturated','condensate'][saturated],vaporFlow:x==null?null:flow*x,liquidFlow:x==null?null:flow*(1-x),saturation:result.saturation};
}
function turbineInverse(mode,p1,T1,p2,power,known,model='IF97'){
 if(!['flow','efficiency'].includes(mode)||!Number.isFinite(power)||power<=0||!Number.isFinite(known)||known<=0)throw Error('Для зворотного розрахунку потужність і відомий параметр мають бути додатними.');
 if(mode==='flow'){const unit=turbine(p1,T1,p2,known,1,model);return turbine(p1,T1,p2,known,power/unit.work,model);}
 const ideal=turbine(p1,T1,p2,1,known,model);const eta=power/ideal.power;return turbine(p1,T1,p2,eta,known,model);
}
// Every sample is evaluated by the selected model. Renderers join samples without spline overshoot.
function diagramData(model='IF97'){
 const dome=[[],[]],isobars=[];
 for(let i=0;i<=180;i++){
  const T=(model==='IF97'?273.15:273.16)+((model==='IF97'?TC:TC-.0001)-(model==='IF97'?273.15:273.16))*Math.sin(i/180*Math.PI/2);
  try{const q=calculate('satt',T,undefined,model).saturation;dome[0].push(q.liquid);dome[1].push(q.vapor);}catch{dome[0].push(null);dome[1].push(null);}
 }
 for(const p of [.01,.1,1,10,22.064,50,100]){
  // Sort parameter records, not states: failed evaluations must retain their
  // temperature position and break the line instead of being moved to its start.
  const samples=[];
  for(let i=0;i<=100;i++){const T=(model==='IF97'?273.15:273.16)+(1073.15-(model==='IF97'?273.15:273.16))*i/100;let q=null;try{q=calculate('pt',p,T,model).state||null;}catch{}samples.push({T,q});}
  if(p<PC){const sat=calculate('satp',p,undefined,model).saturation;for(let i=0;i<=10;i++)samples.push({T:sat.T,order:i,q:calculate('px',p,i/10,model).state});}
  // IF97 supplies an exact critical state. Without this anchor the adaptive
  // sampler hits its depth limit and draws a chord past the critical marker.
  // IAPWS-95 intentionally does not evaluate the singular critical state.
  if(p===PC&&model==='IF97')samples.push({T:TC,q:calculate('pt',PC,TC,model).state});
  samples.sort((a,b)=>a.T-b.T||(a.order??0)-(b.order??0));
  const points=samples.map(sample=>sample.q);
  isobars.push({p,points});
 }
 return {dome,isobars};
}

function throttle(p1,x,p2,model='IF97'){
 if(!Number.isFinite(p1)||!Number.isFinite(p2)||!Number.isFinite(x)||p2<=0||p2>=p1||x<0||x>1)throw Error('Потрібні 0 < P₂ < P₁ і сухість 0…1.');
 const inlet=calculate('px',p1,x,model).state,outlet=calculate('ph',p2,inlet.h,model).state;
 return {inlet,outlet};
}


// src/exergy.js
function referenceState(p0=.101325,T0=298.15,model='IF97'){
 if(!Number.isFinite(p0)||!Number.isFinite(T0))throw Error('Параметри довкілля мають бути скінченними.');
 const ref=calculate('pt',p0,T0,model).state;
 if(!ref||ref.critical)throw Error('Довкілля має задавати однозначний однофазний стан P₀–T₀.');
 return ref;
}
// Specific physical FLOW exergy; no chemical, kinetic or potential contribution.
function flowExergy(state,ref){return (state.h-ref.h)-ref.T*(state.s-ref.s);}
function withExergy(result,ref){const add=s=>({...s,ex:flowExergy(s,ref)});return {...result,...(result.state?{state:add(result.state)}:{}),...(result.saturation?{saturation:{...result.saturation,liquid:add(result.saturation.liquid),vapor:add(result.saturation.vapor)}}:{}),...(result.alternatives?{alternatives:result.alternatives.map(add)}:{})};}


// src/engineering.js
function compression(kind,p1,T1,p2,eta,flow=1,model='IF97'){
 if(!['pump','compressor'].includes(kind))throw Error('Невідомий процес стиснення.');
 if(![p1,T1,p2,eta,flow].every(Number.isFinite)||p2<=p1||flow<0||eta<=0||eta>1)throw Error('Потрібні p₂ > p₁, витрата ≥ 0 і 0 < ККД ≤ 1.');
 const inlet=calculate('pt',p1,T1,model).state;if(!inlet)throw Error('Потрібен однозначний однофазний вхід P–T.');
 const liquid=inlet.region===1||inlet.phase.includes('рідина');
 if(kind==='pump'&&!liquid)throw Error('Для насоса потрібна рідина на вході.');
 if(kind==='compressor'&&(liquid||(inlet.T<TC&&inlet.rho>322)))throw Error('Для компресора потрібен паровий стан на вході.');
 const ideal=calculate('ps',p2,inlet.s,model).state,work=(ideal.h-inlet.h)/eta;
 if(work<=0)throw Error('Перепад ентальпії стиснення має бути додатним.');
 const outlet=calculate('ph',p2,inlet.h+work,model).state;
 return {inlet,ideal,outlet,work,power:flow*work,eta,flow};
}
function heatExchanger(pHot,THot,pHotOut,flowHot,pCold,TCold,pColdOut,flowCold,heat,model='IF97'){
 if(![pHot,THot,pHotOut,flowHot,pCold,TCold,pColdOut,flowCold,heat].every(Number.isFinite)||flowHot<=0||flowCold<=0||heat<0||pHotOut<=0||pColdOut<=0||pHotOut>pHot||pColdOut>pCold)throw Error('Потрібні додатні витрати, Q ≥ 0 та вихідні тиски не вищі за вхідні.');
 const inlet=calculate('pt',pHot,THot,model).state,coldInlet=calculate('pt',pCold,TCold,model).state;
 if(!inlet||!coldInlet)throw Error('Входи теплообмінника мають бути однозначними P–T.');
 if(THot<=TCold)throw Error('Гарячий вхід має бути теплішим за холодний.');
 const outlet=calculate('ph',pHotOut,inlet.h-heat/flowHot,model).state,coldOutlet=calculate('ph',pColdOut,coldInlet.h+heat/flowCold,model).state;
 // Counter-current terminal pinch feasibility. No UA or internal profile is inferred.
 if(outlet.T<coldInlet.T-1e-7||coldOutlet.T>inlet.T+1e-7)throw Error('Задана теплова потужність спричиняє перетин температур на кінцях протитечійного теплообмінника.');
 return {inlet,outlet,coldInlet,coldOutlet,flow:flowHot,coldFlow:flowCold,heat,power:heat,hotDrop:inlet.h-outlet.h,coldRise:coldOutlet.h-coldInlet.h};
}
function engineeringStates(result){return [['Вхід',result.inlet],...(result.ideal?[['Ізоентропний вихід',result.ideal]]:[]),['Вихід',result.outlet],...(result.coldInlet?[['Холодний вхід',result.coldInlet],['Холодний вихід',result.coldOutlet]]:[])];}
function engineeringCSV(kind,result,system='si'){
 const convert=(k,v,u)=>system==='english'?englishProperty(k,v,u):[v,u];
 const head=['state',...['p','T','h','s','x'].map(k=>`${k} [${convert(k,null,{p:'MPa',T:'K',h:'kJ/kg',s:'kJ/(kg K)',x:'-'}[k])[1]}]`)];
 const metrics=[['power',result.power,'kW'],['flow',result.flow,'kg/s'],...(result.work!=null?[['work',result.work,'kJ/kg'],['eta',result.eta,'-']]:[['coldFlow',result.coldFlow,'kg/s']])];
 return '\uFEFF'+[head.join(';'),...engineeringStates(result).map(([name,q])=>[name,...['p','T','h','s','x'].map(k=>convert(k,q[k],'')[0]??'')].join(';')),'',`process;${kind}`,`model;${result.inlet.model||'IF97'}`,'pressure_basis;absolute','quantity;value;unit',...metrics.map(([k,v,u])=>{const [a,b]=convert(k==='coldFlow'?'flow':k,v,u);return `${k};${a};${b}`;})].join('\r\n');
}


