  const signature=[action,status,uiTranslator.language,form?.dataset.calculated,form?.dataset.model,kind,mode].join('|');if(guide.dataset.context===signature)return;guide.dataset.context=signature;guide.dataset.status=status;guide.replaceChildren();
  const badge=document.createElement('span');badge.className='method-badge '+status;badge.textContent=uiTranslator.t(action==='coursework'&&kind==='reactor'?'catalog.status.inDevelopment':'catalog.status.'+status);const summary=document.createElement('p');summary.className='tool-context-summary';summary.append(badge,document.createTextNode(' '+uiTranslator.t('tool.'+action+'.description')));guide.append(summary);
