function renderProcessOutput(kind,r){uiBeforeResultRender();
 const tur=kind==='turbine';
 const labels={work:'Питома робота',power:'Потужність потоку',flow:tur?'Витрата пари':'Вхідна витрата',consumption:'Питома витрата пари',efficiency:'Ізоентропний ККД',inletTsat:'Температура насичення на вході',outletSuperheat:'Перегрів на виході',vaporFlow:'Витрата пари',liquidFlow:'Витрата рідини',vaporFraction:'Пароутворення'};
 const metrics=processSummary(kind,r).map(([key,value,unit])=>{const displayKey=key==='inletTsat'?'T':key==='outletSuperheat'?'dT':key.endsWith('Flow')?'flow':['efficiency','vaporFraction'].includes(key)?'eta':key;
  const v=key==='inletTsat'&&value!=null?value-273.15:['efficiency','vaporFraction'].includes(key)&&value!=null?value*100:value;
  return {key,label:labels[key],value:v,displayKey,unit:['efficiency','vaporFraction'].includes(key)?'%':unit};});
 $('process-result').innerHTML=`<p class="result-metrics">${metrics.map(m=>`<span data-process-metric="${m.key}">${m.label}: <strong>${format(processDisplay(m.displayKey,m.value,m.unit)[0])} ${processDisplay(m.displayKey,m.value,m.unit)[1]}</strong>${m.value==null?`<small>${processMetricReason(m.key,r)}</small>`:''}</span>`).join('')}</p>${!tur&&r.outlet.x==null?'<p>Вихід однофазний; баланс сепарації на рідину й пару не застосовується.</p>':''}<table><thead><tr><th>Стан</th>${[['p','МПа'],['T','°C'],['h','кДж/кг'],['s','кДж/(кг·K)']].map(([k,u])=>`<th>${k}, ${processDisplay(k,null,u)[1]}</th>`).join('')}<th>x</th><th>Фаза</th></tr></thead><tbody>${[['Вхід',r.inlet],...(tur?[['Ізоентропний вихід',r.ideal]]:[]),['Вихід',r.outlet]].map(([l,q])=>`<tr><td>${l}</td>${[['p',q.p],['T',q.T-273.15],['h',q.h],['s',q.s],['x',q.x]].map(([k,v])=>`<td>${format(processDisplay(k,v,'')[0])}</td>`).join('')}<td>${q.phase}</td></tr>`).join('')}</tbody></table><button id="process-csv">CSV процесу</button><button id="process-history">Додати кінцеві стани до журналу</button><button id="process-plot">Нанести процес на h–s діаграму</button><button id="process-plot-ph">Показати на P–h</button><button id="process-transfer">Показати вихід у загальних властивостях</button>`;
 $('process-history').onclick=()=>{for(const [name,q] of [['Вхід',r.inlet],['Вихід',r.outlet]])historyStates.unshift({...q,name:processLabel(kind)+' · '+name,source:q.critical?{mode:'pt',a:q.p,b:q.T}:{mode:'ph',a:q.p,b:q.h}});historyStates.splice(500);renderHistory();saveProject();$('process-history').disabled=true;};
 attachSpreadsheetExport($('process-csv'),spreadsheetOptions('process-spreadsheet',()=>processTabular(kind,r,spreadsheetContext(kind,r.inlet.model||'IF97'))));
 $('process-csv').onclick=()=>downloadFile(processCSV(kind,r,$('output-system').value),kind+'.csv','text/csv;charset=utf-8');
 $('process-plot').addEventListener('click',()=>{showProcess('hsdiagram');$('diagram-fit-process').click();});
 $('process-plot-ph').onclick=()=>{showProcess('phdiagram');$('diagram-fit-process').click();};
 $('process-transfer').addEventListener('click',()=>{selectView('general');$('mode').value='ph';resetMode();uiSetValue($('input-a'),String(pressureOutput(r.outlet.p,'MPa',pressureSettings)));uiSetValue($('input-b'),String(r.outlet.h));run();});
}
