 function updatePointList(){$('diagram-point').disabled=!choices.length;for(const [chart,global] of [['diagram-system','output-system'],['diagram-energy','output-energy'],['diagram-digits','display-digits']])$(chart).value=$(global).value;const chosen=selected;$('diagram-point').innerHTML='<option value="">Виберіть стан</option>'+choices.map(([q,label],i)=>`<option value="${i}" ${customDiagramLabel(q)?'data-i18n-ignore':''}>${i+1}. ${escapeHTML(label)} · ${dt('p',q.p)} · ${dt('T',q.T-273.15)}</option>`).join('');$('diagram-point').value=chosen==null?'':String(chosen);}
