  chart.data.datasets=chartDiagramDatasets(kind,renderCache(),choices,diagramPlan,process,hiddenIsobars,colors,selected,activeGuides(),{range,width:plot?.width||width,height:plot?.height||height,model:modelValue()}).map(d=>Object.assign(previousDatasets.get(d.id)||{},d));
