function inputCaption(el){const label=el.closest('label')?.cloneNode(true);if(label){label.querySelectorAll('input,select,button').forEach(n=>n.remove());return label.textContent.trim();}return document.querySelector(`label[for="${el.id}"]`)?.textContent||el.id;}
function panelForm(){return document.querySelector('#cc-form,#wp-form,#process-form,#engineering-form,#learn-form,#scientific-form,#batch-form,#flow-form,#tutorial-form,#satgrid-form,#npp-form,#exchanger-form,#lab-form,#cw-form');}
function panelInputs(form){if(form.id==='cc-form')return {'cc-data':$('cc-data').value};const fields=form.id==='batch-form'?$('process-view').querySelectorAll('input,select,textarea'):form.querySelectorAll('input,select,textarea');return Object.fromEntries([...fields].filter(el=>el.id&&el.type!=='file').map(el=>[el.id,uiStoredValue(el)]));}
function capturePanel(){if(restoringWorkspace)return;const form=panelForm();if(!form||!WORKSPACE_PANELS.includes(activeSection))return;panelRecords[activeSection]={inputs:panelInputs(form),calculated:form.dataset.calculated==='true',model:form.dataset.model||modelValue(),...(form.dataset.source?{source:form.dataset.source}:{})};}
function panelEdited(form){form.dataset.calculated='false';form.dataset.workflowTouched='true';uiResultActions(true);}
function panelCalculated(form,source,model=modelValue()){form.dataset.calculated='true';form.dataset.model=model;uiResultActions(true);if(source)form.dataset.source=source;capturePanel();saveProject();}
function restorePanelInputs(kind,form){
 const record=panelRecords[kind];if(!record)return false;
 const previous=restoringWorkspace;restoringWorkspace=true;
 try{
  // Select handlers build dependent options and visibility first; restore text values last.
  for(const el of form.querySelectorAll('select'))if(record.inputs[el.id]!=null){el.value=record.inputs[el.id];el.dispatchEvent(new Event('change',{bubbles:true}));}
  // Unit controls may be created by the select handlers above. Set them before
  // converting canonical stored input values; JSON field order is not a unit contract.
  for(const [id,value] of Object.entries(record.inputs)){const el=$(id);if(el?.tagName==='SELECT'){el.value=value;el.dataset.previous=value;}}
  for(const [id,value] of Object.entries(record.inputs)){const el=$(id);if(el&&el.tagName!=='SELECT')uiSetValue(el,value);}
 }finally{restoringWorkspace=previous;}
 return record.calculated;
}
function restorePanelResult(kind,form,ready=Promise.resolve()){
 const record=panelRecords[kind];if(!record?.calculated)return;
 ready.then(()=>{if(!form.isConnected||activeSection!==kind)return;if(form.id==='batch-form'&&record.source==='csv')$('batch-import').click();else form.requestSubmit();}).catch(()=>{});
}
function openSection(kind){if(['general','saturation','help'].includes(kind))selectView(kind);else if(['ts','hsdiagram','phdiagram','turbine','flash'].includes(kind))showProcess(kind);else if(kind==='batch')showBatch();else if(kind==='satgrid')showSaturationGrid();else if(kind==='engineering')showEngineering();else if(kind==='flow')showFlow();else if(kind==='libraries')showPythonLibraries();else if(kind==='water-process')showWaterProcess();else if(kind==='custom-cycle')showCustomCycle();else if(kind==='npp')showNuclear();else if(kind==='study')showStudyReport();else if(kind==='research')showResearch();else if(kind==='exchanger')showExchanger();else if(kind==='projects')showProjectLibrary();else if(kind==='coursework')showCoursework();else if(kind==='laboratory')showLaboratory();else if(kind==='tutorials')showTutorials();else if(['boundaries','comparison'].includes(kind))scientificPanel(kind);else learningPanel(kind);}
const STORAGE_KEY='water-steam-if97-project-v1';
let importedProjectMetadata=null,recoveryProjectText=null,recoveryNeedsBackup=false,projectImportSequence=0;
const RECOVERY_KEY=STORAGE_KEY+'-recovery';
function projectSnapshot(){capturePanel();return {savedWith:exportMetadata(APP_BUILD,'project / multiple methods','per result'),...(importedProjectMetadata?{importedFrom:importedProjectMetadata}:{}),research:researchState,study:studyReport,format:'water-steam-if97',version:1,uiUnits:uiUnitPreferences,uiInputDefaults,digits:displayDigits,diagram:diagramWorkspaceSnapshot(diagramPlan,historyStates),pressure:pressureSettings,title:$('project-title').value,history:historyStates.map(q=>({p:q.p,h:q.h,model:q.model||'IF97',name:q.name||'',...(q.source?{source:q.source}:{})})),workspace:{active:activeSection,panels:panelRecords},process:storedProcess,form:{calculated:!!last,roundingDisplay:accountForInputRounding,...(last?.diagnostics?.selection==='manual'?{selectedRoot:{p:last.state.p,T:last.state.T}}:{}),inputStyle,inputOrder:inputReversed?'reverse':'canonical',model:modelValue(),mode:$('mode').value,a:$('input-a').value,b:$('input-b').value,ua:$('unit-a').value,ub:$('unit-b').value},drafts:processDrafts,ambient,system:$('output-system').value,energy:$('output-energy').value,gray:document.body.classList.contains('gray'),scale:$('ui-scale').value,hints:hintsEnabled};}
function saveProject(){if(!persistenceReady||restoringWorkspace)return;try{const text=JSON.stringify(projectSnapshot());if(recoveryNeedsBackup){localStorage.setItem(RECOVERY_KEY,recoveryProjectText);recoveryNeedsBackup=false;}localStorage.setItem(STORAGE_KEY,text);unsavedProject=false;$('project-save-status').textContent='Збережено локально · JSON для резервної копії';}catch{unsavedProject=true;$('project-save-status').textContent='Є незбережені зміни — експортуйте JSON';$('result-status').textContent='Локальне збереження недоступне — експортуйте проєкт у файл';}}
function applyProject(p){restoringWorkspace=true;try{uiUnitPreferences=readUIUnits(p.uiUnits);uiInputDefaults=p.uiInputDefaults===true;uiSyncPreferences();importedProjectMetadata=p.importedFrom||p.savedWith||null;researchState=p.research||readResearch(null);researchSource=null;studyReport=p.study||readStudyReport(null);smartDrafts.clear();capturePanel();for(const key of Object.keys(panelRecords))delete panelRecords[key];Object.assign(panelRecords,p.workspace.panels);displayDigits=p.digits;accountForInputRounding=p.form.roundingDisplay===true;uiSetValue($('display-digits'),String(displayDigits));diagramPlan=p.diagram;diagramRanges.clear();diagramIsobars.clear();pressureSettings=p.pressure;syncPressureControls();diagramCache=null;selectModel(p.form.model||'IF97');$('project-title').value=p.title;historyUndo=null;historyStates.splice(0,historyStates.length,...p.states);revision=p.states.length;ambient=p.ambient;ambientRef=referenceState(ambient.p,ambient.T);uiSetValue($('ambient-p'),String(ambient.p));uiSetValue($('ambient-t'),String(ambient.T-273.15));selectView('general');$('mode').value=p.form.mode;resetMode();for(const [id,v] of [['input-a',p.form.a],['input-b',p.form.b],['unit-a',p.form.ua],['unit-b',p.form.ub]])$(id).value=v;for(const id of ['unit-a','unit-b']){if(!$(id).value)throw Error('Одиниці не відповідають режиму.');$(id).dataset.previous=$(id).value;}inputStyle=p.form.inputStyle||'smart';inputReversed=p.form.inputOrder==='reverse'&&!p.form.mode.startsWith('sat')&&inputStyle==='smart';syncSmartInput();Object.keys(processDrafts).forEach(k=>delete processDrafts[k]);Object.assign(processDrafts,p.drafts);storedProcess=p.process?{type:p.process.type,args:p.process.args,model:p.process.model||'IF97'}:null;plottedProcess=p.process?{kind:processLabel(p.process.type),result:p.process.result}:null;$('output-system').value=p.system;$('output-energy').value=p.energy;document.body.classList.toggle('gray',p.gray);hintsEnabled=p.hints!==false;$('hints-toggle').setAttribute('aria-pressed',String(hintsEnabled));if(!hintsEnabled)openGlossary.clear();$('ui-scale').value=p.scale;document.documentElement.style.setProperty('--ui-scale',p.scale);renderHistory();invalidate();if(p.result){last=p.result;render();$('result-status').textContent='Відновлено результат проєкту';}const active=p.workspace.active;if(active!=='general'&&active!=='saturation')openSection(active);else if(active==='saturation'){activeSection='saturation';$('tab-general').setAttribute('aria-selected','false');$('tab-saturation').setAttribute('aria-selected','true');}}finally{restoringWorkspace=false;}}
async function restoreLocal(){let text=null;try{recoveryProjectText=localStorage.getItem(RECOVERY_KEY);recoveryExport.disabled=recoveryProjectText===null;text=localStorage.getItem(STORAGE_KEY);if(text){const raw=JSON.parse(text);if(!raw.workspace){const panels={};for(const kind of ['gases','humid','cycles','ice','d2o','seawater']){try{const inputs=JSON.parse(localStorage.getItem('water-steam-learning-'+kind)||'null');if(inputs)Object.assign(panels,readWorkspace({active:kind,panels:{[kind]:{inputs,calculated:false,model:raw.form?.model||'IF97'}}}).panels);}catch{}}raw.workspace={active:'general',panels};}const before=JSON.stringify(projectSnapshot()),p=await projectReader.readProject(JSON.stringify(raw));if(JSON.stringify(projectSnapshot())!==before)throw Error('Project changed during restore');applyProject(p);}}catch{if(text!==null){recoveryProjectText=text;recoveryNeedsBackup=true;recoveryExport.disabled=false;}unsavedProject=true;$('project-save-status').textContent=uiTranslator.text('Проєкт не відновлено; оригінал збережено для відновлення');$('result-status').textContent=uiTranslator.text('Збережений проєкт не відновлено; завантажте оригінал через меню Файл');}}
function downloadFile(content,name,type,options={}){if(options.metadata!==false){let method=options.method||activeSection,model=options.model||modelValue();if(type.startsWith('application/json')){const data=JSON.parse(content);method=options.method||data.module||(data.format==='water-steam-if97'?'project / multiple methods':method);model=options.model||data.model||model;}if(method==='coursework')method='coursework / '+($('cw-kind')?.value||'')+($('cw-kind')?.value==='reactor'?' / '+REACTOR_METHOD_VERSION:'');if(['study','projects','project / multiple methods','history','gases','humid','cycles','ice','d2o','seawater','flow','exchanger','comparison','boundaries','laboratory'].includes(method))model='per result';if(method==='study'&&studyReport.entries.some(e=>e.kind==='coursework'&&e.input.kind==='reactor'))method+=' / '+REACTOR_METHOD_VERSION;content=exportWithMetadata(content,type,exportMetadata(APP_BUILD,method,model),uiTranslator.language==='en');}if(type.startsWith('text/html'))content=localizedDocument(content);else if(type.startsWith('image/svg+xml'))content=localizedDocument(content,'image/svg+xml');const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const fileMenu=document.querySelector('.menubar .menu');
const projectExport=document.createElement('button');projectExport.id='file-project-export';projectExport.innerHTML=icon('download')+'Експорт проєкту JSON';projectExport.onclick=()=>{try{downloadFile(JSON.stringify(projectSnapshot(),null,2),'water-steam-project.json','application/json');unsavedProject=false;$('project-save-status').textContent='JSON підготовлено для збереження';fileMenu.closest('details').open=false;}catch(e){unsavedProject=true;$('project-save-status').textContent=uiTranslator.text('Не вдалося підготувати JSON: ')+e.message;}};fileMenu.append(projectExport);
const recoveryExport=document.createElement('button');recoveryExport.id='file-recovery';recoveryExport.textContent='Завантажити оригінал для відновлення';recoveryExport.disabled=true;recoveryExport.onclick=()=>{if(recoveryProjectText!==null)downloadFile(recoveryProjectText,'water-steam-project-recovery.json','application/json',{metadata:false});};fileMenu.append(recoveryExport);
const projectImport=document.createElement('button');projectImport.innerHTML=icon('upload')+'Імпорт проєкту / розрахунку JSON';const projectFile=document.createElement('input');projectFile.type='file';projectFile.accept='.json,application/json';projectFile.hidden=true;document.body.append(projectFile);projectImport.onclick=()=>{fileMenu.closest('details').open=false;projectFile.click();};fileMenu.append(projectImport);
projectFile.onchange=async()=>{const file=projectFile.files[0];if(!file)return;cancelCalculation();cancelCustomCycle();cancelWaterProcess();cancelGasTables();projectReader.cancel();const sequence=++projectImportSequence,before=JSON.stringify(projectSnapshot());try{if(file.size>2000000)throw Error('Файл завеликий (максимум 2 МБ).');const text=await file.text();if(sequence!==projectImportSequence)return;if(JSON.stringify(projectSnapshot())!==before)throw Error(uiTranslator.text('Проєкт змінено під час читання файлу; повторіть імпорт'));if(JSON.parse(text)?.format==='water-steam-if97'){const p=await projectReader.readProject(text);if(sequence!==projectImportSequence)return;if(JSON.stringify(projectSnapshot())!==before)throw Error(uiTranslator.text('Проєкт змінено під час читання файлу; повторіть імпорт'));applyProject(p);$('result-status').textContent='Проєкт імпортовано';}else{const q=readCalculation(text);capturePanel();panelRecords[q.module]=q.record;if(['cycles','turbine','flash','engineering','batch','flow','satgrid','coursework'].includes(q.module)&&q.record.model!==modelValue()){selectModel(q.record.model);diagramCache=null;invalidate();}const previousRestore=restoringWorkspace;restoringWorkspace=true;try{openSection(q.module);}finally{restoringWorkspace=previousRestore;}$('result-status').textContent='Розрахунок імпортовано; результати обчислюються з входів';}saveProject();}catch(e){if(sequence!==projectImportSequence)return;$('error').textContent='Імпорт: '+(e.code==='unavailable'?uiTranslator.t('calculator.workerFailed'):e.code==='timeout'?uiTranslator.t('calculator.timeout'):e.message);$('error').hidden=false;$('result-status').textContent='Не вдалося імпортувати проєкт';if(activeSection==='custom-cycle'&&$('cc-error')){$('cc-error').textContent=$('error').textContent;$('cc-error').hidden=false;$('cc-status').textContent=uiTranslator.language==='en'?'Project import failed; current cycle preserved.':'Імпорт не вдався; поточний цикл збережено.';}}if(sequence===projectImportSequence)projectFile.value='';};
document.addEventListener('input',e=>{if(e.target.closest('#calculator')||e.target.id==='project-title'||e.target.closest('#process-view'))saveProject();});
document.addEventListener('change',e=>{if(e.target.type!=='file')saveProject();});document.addEventListener('click',e=>{if(e.target.closest('[data-action],[data-p]'))queueMicrotask(saveProject);});
window.addEventListener('pagehide',saveProject);

$('ambient-apply').onclick=()=>{try{const next={p:uiNumber('ambient-p'),T:uiNumber('ambient-t')+273.15};const ref=referenceState(next.p,next.T);ambient=next;ambientRef=ref;$('ambient-status').textContent=`Застосовано P₀=${format(ambient.p)} МПа, T₀=${format(ambient.T)} K · ${ref.phase}`;if(last)render();saveProject();}catch(e){$('ambient-status').textContent=e.message;}};

$('output-system').addEventListener('change',()=>{uiUnitPreferences=$('output-system').value==='english'?readUIUnits({temperature:'F',pressure:'psi',mass:'lbs',power:'Btuh',length:'ft',energy:'Btulb'}):readUIUnits(null);uiSyncPreferences();if(last)render();else $('results').innerHTML=propertyTable(null);renderHistory();if($('steam-diagram')&&!$('process-view').hidden)diagramRedraw?.();if($('batch-results'))renderBatch();if($('satgrid-results'))renderSaturationGrid();if($('process-form')?.dataset.calculated==='true'&&storedProcess?.type===activeSection&&plottedProcess)renderProcessOutput(activeSection,plottedProcess.result);
 refreshGasTableResult();if($('npp-results'))renderNuclear();if($('flow-results'))renderFlow();if($('eng-result'))renderEngineering();if(!$('process-view').hidden&&$('process-form')&&$('process-result')?.textContent.trim())$('process-form').requestSubmit();saveProject();});

function escapeHTML(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
let batchResults=[];
function showBatch(){
 selectView('panel');activeSection='batch';batchResults=[];$('calculator-view').hidden=true;$('process-view').hidden=false;document.querySelector('[data-action="batch"]').setAttribute('aria-selected','true');$('tab-general').setAttribute('aria-selected','false');
 $('process-view').innerHTML=`<h2>Пакетні розрахунки</h2><p>До 500 точок. Помилки залишаються в таблиці; P–T на насиченні показує дві фази. Тиски абсолютні.</p><form id="batch-form"><fieldset><legend>Серія за діапазоном</legend><label>Режим<select id="batch-mode">${['pt','ph','ps','satp','satt','px','tx','hs','th','ts','prho','trho','pv','tv','pu','tu','us','vs','hv','uv'].map(m=>`<option>${m}</option>`).join('')}</select></label><label>Змінний параметр<select id="batch-vary"><option value="b">Другий</option><option value="a">Перший</option></select></label><label>Одиниця першого<select id="batch-ua"></select></label><label>Одиниця другого<select id="batch-ub"></select></label>${[['start','Початок','30'],['end','Кінець','300'],['count','Кількість точок','10'],['fixed','Фіксований параметр','3']].map(([id,label,v])=>`<label>${label}<input id="batch-${id}" value="${v}" required inputmode="decimal"></label>`).join('')}</fieldset><button>Розрахувати серію</button></form><fieldset><legend>Вхідний CSV</legend><p>mode,a,b,unit_a,unit_b,name · коди одиниць: MPa, bar, psi, C, K, F, kJkg, kJkgK, Btulb, BtulbR, fraction. Роздільник кома або крапка з комою.</p><label for="batch-text">Дані CSV</label><textarea id="batch-text" rows="5">mode,a,b,unit_a,unit_b,name
pt,3,300,MPa,K,Рідина
px,0.1,0.5,MPa,fraction,Суміш</textarea><input type="file" id="batch-file" accept=".csv,text/csv" aria-label="Відкрити CSV"><button id="batch-import">Розрахувати CSV</button><button id="batch-example">Зберегти зразок CSV</button></fieldset><p id="batch-error" role="alert"></p><div id="batch-results"></div>`;
 function resetBatch(){const m=$('batch-mode').value,u=batchUnits(m);options('batch-ua',u.a.map(x=>[x,x]));options('batch-ub',u.b.map(x=>[x,x]));const sat=m.startsWith('sat');$('batch-ub').disabled=sat;$('batch-fixed').disabled=sat;$('batch-vary').disabled=sat;if(sat)$('batch-vary').value='a';}
 resetBatch();$('batch-mode').onchange=resetBatch;
 function clearBatch(){panelEdited($('batch-form'));batchResults=[];$('batch-results').replaceChildren();$('batch-error').textContent='';}
 $('batch-form').oninput=clearBatch;$('batch-form').addEventListener('change',clearBatch);$('batch-text').oninput=clearBatch;
 function evaluateBatch(inputs,source){$('batch-error').textContent='';batchResults=calculateBatch(inputs,modelValue());renderBatch();panelCalculated($('batch-form'),source);}
 $('batch-form').onsubmit=e=>{e.preventDefault();clearBatch();try{evaluateBatch(batchRange({mode:$('batch-mode').value,vary:$('batch-vary').value,...Object.fromEntries(['start','end','count','fixed'].map(k=>[k,$('batch-'+k).disabled?0:uiNumber('batch-'+k)])),ua:$('batch-ua').value,ub:$('batch-ub').value}),'range');}catch(e){$('batch-error').textContent=e.message;}};
 $('batch-import').onclick=()=>{clearBatch();try{evaluateBatch(parseBatchCSV($('batch-text').value),'csv');}catch(e){$('batch-error').textContent=e.message;}};
 $('batch-file').onchange=async()=>{try{const f=$('batch-file').files[0];if(!f)return;if(f.size>1000000)throw Error('CSV завеликий (1 МБ).');clearBatch();$('batch-text').value=await f.text();saveProject();$('batch-error').textContent='Файл відкрито — натисніть «Розрахувати CSV».';}catch(e){$('batch-error').textContent=e.message;}};
 $('batch-example').onclick=()=>downloadFile($('batch-text').value,'water-steam-input.csv','text/csv;charset=utf-8',{metadata:false});restorePanelInputs('batch',$('batch-form'));restorePanelResult('batch',$('batch-form'));
}
function renderBatch(){if(!$('batch-results'))return;const keys=['p','T','h','s','x'];$('batch-results').innerHTML=`<p>Рядків: ${batchResults.length}; успішних: ${batchResults.filter(r=>!r.error).length}; помилок: ${batchResults.filter(r=>r.error).length}.</p><button id="batch-export">CSV результатів</button><button id="batch-history">Додати успішні стани до журналу</button><table><thead><tr><th>Назва</th>${keys.map(k=>`<th>${k} [${display(k,null,rows.find(r=>r[0]===k)[3])[1]}]</th>`).join('')}<th>Фаза / помилка</th></tr></thead><tbody>${batchResults.map(r=>r.error?`<tr><td data-i18n-ignore>${escapeHTML(r.input.name)}</td><td colspan="6">${escapeHTML(r.error)}</td></tr>`:batchStates(r).map(q=>`<tr><td data-i18n-ignore>${escapeHTML(r.input.name)}</td>${keys.map(k=>`<td>${format(display(k,k==='T'?q.T-273.15:q[k],rows.find(r=>r[0]===k)[3])[0])}</td>`).join('')}<td>${q.phase}</td></tr>`).join('')).join('')}</tbody></table>`;
 attachSpreadsheetExport($('batch-export'),spreadsheetOptions('batch-spreadsheet',()=>batchTabular(batchResults,spreadsheetContext('batch','per result'))));
 $('batch-export').onclick=()=>downloadFile(batchCSV(batchResults,$('output-system').value,$('output-energy').value),'water-steam-batch.csv','text/csv;charset=utf-8');$('batch-history').onclick=()=>{for(const r of batchResults)for(const q of batchStates(r))historyStates.unshift({...q,name:r.input.name});historyStates.splice(500);renderHistory();saveProject();$('batch-history').disabled=true;};}

function processLabel(kind){return {turbine:'Турбіна',flash:'Дроселювання',throttle:'Дроселювання',pump:'Насос',compressor:'Компресор','heat-exchanger':'Теплообмінник'}[kind]||kind;}
let engineeringResult=null,engineeringKind='compressor';
function showEngineering(){
 selectView('panel');activeSection='engineering';$('calculator-view').hidden=true;$('process-view').hidden=false;document.querySelector('[data-action="engineering"]').setAttribute('aria-selected','true');$('tab-general').setAttribute('aria-selected','false');const draft=processDrafts.engineering||{};
 $('process-view').innerHTML=`<h2>Насос, компресор і теплообмінник</h2><p>Насос/компресор: адіабатичне стиснення, h₂=h₁+(h₂s−h₁)/η. Теплообмінник: протитечійний баланс двох потоків без втрат у довкілля; перевірка кінцевих температур. Площа, UA та внутрішній температурний профіль не визначаються.</p><form id="engineering-form"><label>Процес<select id="eng-mode"><option value="compressor">Компресор</option><option value="pump">Насос</option><option value="heat-exchanger">Теплообмінник</option></select></label><fieldset><legend>Одиниці · ${pressureBasisLabel()} тиск</legend><label>Тиск<select id="eng-pressure">${PU.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Температура<select id="eng-temperature">${TU.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Витрата<select id="eng-mass"><option value="kgs">кг/с</option><option value="kgh">кг/год</option><option value="lbs">lb/s</option><option value="lbh">lb/h</option></select></label><label>Теплова потужність<select id="eng-power-unit"><option value="kW">кВт</option><option value="Btuh">Btu/h</option></select></label></fieldset><fieldset><legend>Потік / гарячий потік</legend>${[['p1','Вхідний тиск','0.1'],['t1','Вхідна температура','150'],['p2','Вихідний тиск','1'],['eta','Ізоентропний ККД, %','80'],['flow','Масова витрата','1'],['power','Теплова потужність Q','100']].map(([k,l,v])=>`<label>${l}<input id="eng-${k}" value="${v}" required inputmode="decimal"></label>`).join('')}</fieldset><fieldset id="eng-cold"><legend>Холодний потік</legend>${[['pc1','Холодний вхідний тиск','0.1'],['tc1','Холодна вхідна температура','20'],['pc2','Холодний вихідний тиск','0.1'],['coldflow','Холодна масова витрата','1']].map(([k,l,v])=>`<label>${l}<input id="eng-${k}" value="${v}" required inputmode="decimal"></label>`).join('')}</fieldset><button>Розрахувати процес</button></form><p id="eng-error" role="alert"></p><div id="eng-result"></div>`;
 for(const k of ['p1','p2','pc1','pc2'])uiSetValue($('eng-'+k),String(pressureOutput(Number($('eng-'+k).value),'MPa',pressureSettings)));
 const ids=['mode','pressure','temperature','mass','power-unit','p1','t1','p2','eta','flow','power','pc1','tc1','pc2','coldflow'];for(const id of ids)if(draft[id])$('eng-'+id).value=draft[id];
 function remember(){processDrafts.engineering=Object.fromEntries(ids.map(id=>[id,uiStoredValue($('eng-'+id))]));saveProject();}
 function mode(){const hx=$('eng-mode').value==='heat-exchanger';$('eng-cold').hidden=!hx;for(const k of ['power','power-unit','pc1','tc1','pc2','coldflow'])$('eng-'+k).disabled=!hx;$('eng-power').closest('label').hidden=!hx;$('eng-power-unit').closest('label').hidden=!hx;$('eng-eta').disabled=hx;$('eng-eta').closest('label').hidden=hx;
 // p1/p2 are shared across modes but their valid relation flips: compressor/pump need p2>p1, heat exchanger needs p2<=p1 (hot-side pressure drop).
 const p1=uiNumber('eng-p1'),p2=uiNumber('eng-p2');
 if(Number.isFinite(p1)&&Number.isFinite(p2)){if(hx&&p2>p1)uiSetValue($('eng-p2'),String(p1));else if(!hx&&p2<=p1)uiSetValue($('eng-p2'),String(p1*10));}}
 mode();$('eng-mode').onchange=()=>{mode();engineeringResult=null;$('eng-result').innerHTML='';remember();};
 for(const id of ['pressure','temperature','mass','power-unit']){const el=$('eng-'+id);el.dataset.previous=el.value;el.onchange=()=>{try{const converted=[];for(const k of id==='pressure'?['p1','p2','pc1','pc2']:id==='temperature'?['t1','tc1']:id==='mass'?['flow','coldflow']:['power']){const input=$('eng-'+k);if(!input.value.trim())continue;const v=uiNumber(input,el.dataset.previous);converted.push([input,String(id==='mass'?massFrom(massTo(v,el.dataset.previous),el.value):id==='power-unit'?v*(el.dataset.previous==='Btuh'?1055.05585262/3600000:1)/(el.value==='Btuh'?1055.05585262/3600000:1):fromCanonical(toCanonical(v,el.dataset.previous),el.value))]);}for(const [input,value] of converted)uiSetValue(input,value);}catch(error){el.value=el.dataset.previous;$('eng-error').textContent=error.message;}el.dataset.previous=el.value;engineeringResult=null;$('eng-result').innerHTML='';remember();};}
 $('engineering-form').addEventListener('change',()=>panelEdited($('engineering-form')));
 $('engineering-form').oninput=()=>{panelEdited($('engineering-form'));engineeringResult=null;$('eng-result').innerHTML='';remember();};
 $('engineering-form').onsubmit=e=>{e.preventDefault();try{const n=k=>{const v=uiNumber('eng-'+k);return ['p1','p2','pc1','pc2'].includes(k)?pressureInput(v,$('eng-pressure').value,pressureSettings):['t1','tc1'].includes(k)?toCanonical(v,$('eng-temperature').value):['flow','coldflow'].includes(k)?massTo(v,$('eng-mass').value):k==='power'&&$('eng-power-unit').value==='Btuh'?v*1055.05585262/3600000:v;};engineeringKind=$('eng-mode').value;const args=engineeringKind==='heat-exchanger'?[n('p1'),n('t1'),n('p2'),n('flow'),n('pc1'),n('tc1'),n('pc2'),n('coldflow'),n('power')]:[n('p1'),n('t1'),n('p2'),n('eta')/100,n('flow')];engineeringResult=engineeringKind==='heat-exchanger'?heatExchanger(...args,modelValue()):compression(engineeringKind,...args,modelValue());storedProcess={type:engineeringKind,args,model:modelValue()};plottedProcess={kind:processLabel(engineeringKind),result:engineeringResult};$('eng-error').textContent='';remember();renderEngineering();panelCalculated($('engineering-form'));}catch(e){panelEdited($('engineering-form'));engineeringResult=null;$('eng-result').innerHTML='';$('eng-error').textContent=e.message;}};
 restorePanelInputs('engineering',$('engineering-form'));restorePanelResult('engineering',$('engineering-form'));
}
function renderEngineering(){uiBeforeResultRender();if(!engineeringResult||!$('eng-result'))return;const r=engineeringResult,keys=['p','T','h','s','x'];const metric=(k,v,u)=>{const [a,b]=processDisplay(k,v,u);return format(a)+' '+b;};$('eng-result').innerHTML=`<p>${engineeringKind==='heat-exchanger'?'Теплова потужність':'Споживана потужність'}: <strong>${metric('power',r.power,'кВт')}</strong>${r.work!=null?' · Робота стиснення: '+metric('work',r.work,'кДж/кг'):''}</p><table><thead><tr><th>Стан</th>${keys.map(k=>`<th>${k} [${processDisplay(k,null,{p:'МПа',T:'°C',h:'кДж/кг',s:'кДж/(кг·K)',x:'–'}[k])[1]}]</th>`).join('')}<th>Фаза</th></tr></thead><tbody>${engineeringStates(r).map(([name,q])=>`<tr><td>${name}</td>${keys.map(k=>`<td>${format(processDisplay(k,k==='T'?q.T-273.15:q[k],'')[0])}</td>`).join('')}<td>${q.phase}</td></tr>`).join('')}</tbody></table><button id="eng-export">CSV процесу</button><button id="eng-history">Додати кінцеві стани до журналу</button><button id="eng-plot">Нанести процес на діаграму</button><button id="eng-plot-ph">Показати на P–h</button>`;
 $('eng-export').onclick=()=>downloadFile(engineeringCSV(engineeringKind,r,$('output-system').value),engineeringKind+'.csv','text/csv;charset=utf-8');$('eng-history').onclick=()=>{for(const [name,q] of engineeringStates(r))historyStates.unshift({...q,name:processLabel(engineeringKind)+' · '+name});historyStates.splice(500);renderHistory();saveProject();$('eng-history').disabled=true;};$('eng-plot').onclick=()=>{showProcess('hsdiagram');$('diagram-fit-process').click();};$('eng-plot-ph').onclick=()=>{showProcess('phdiagram');$('diagram-fit-process').click();};}

const reportExport=document.createElement('button');reportExport.id='file-report';reportExport.innerHTML=icon('report')+'Звіт для друку HTML';reportExport.onclick=()=>{if($('steam-diagram')&&!$('process-view').hidden&&diagramReportContent){if($('diagram-report')?.disabled)return;downloadFile(diagramReportContent(),'diagram-report.html','text/html;charset=utf-8');return;}fileMenu.closest('details').open=false;const states=historyStates.length?historyStates:last?.state?[last.state]:[];const panel=$('process-view').hidden?null:$('process-view').cloneNode(true);let extra='';if(panel&&panelForm()?.dataset.calculated==='true'){const form=panel.querySelector('form');const inputs=[...panelForm().querySelectorAll('input,select')].filter(el=>!el.disabled&&el.type!=='file').map(el=>[inputCaption(el),el.tagName==='SELECT'?el.selectedOptions[0]?.textContent:el.value]);panel.querySelectorAll('details').forEach(d=>d.open=true);panel.querySelectorAll('[data-glossary]').forEach(el=>el.replaceWith(document.createTextNode(el.textContent.trim())));panel.querySelectorAll('form,button,input,textarea').forEach(el=>el.remove());extra='<h2>Поточний розрахунок</h2><table><thead><tr><th>Вхідний параметр</th><th>Значення</th></tr></thead><tbody>'+inputs.map(([name,value])=>`<tr><td>${escapeHTML(name)}</td><td>${escapeHTML(value)}</td></tr>`).join('')+'</tbody></table>'+panel.innerHTML;}if(!states.length&&!extra){$('result-status').textContent='Спочатку розрахуйте хоча б один стан';return;}downloadFile(printableReport($('project-title').value,states,$('output-system').value,$('output-energy').value,{extra,result:last?ambientResult(last):null,ambient,pressure:pressureSettings,preferences:uiUnitPreferences}),'water-steam-report.html','text/html;charset=utf-8',{method:'history + '+activeSection+(activeSection==='coursework'&&$('cw-kind')?.value==='reactor'?' / '+REACTOR_METHOD_VERSION:''),model:'per result'});};fileMenu.append(reportExport);
document.querySelector('[role=tablist]').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...document.querySelectorAll('[role=tab]')].filter(t=>!t.hidden),i=tabs.indexOf(e.target);if(i<0)return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click();});

// Start with room for results on phones; the menu can reveal settings at any time.
if(window.matchMedia('(max-width:700px)').matches)document.body.classList.add('setup-collapsed');
// A native section picker keeps every panel reachable on narrow screens.
const sectionTabs=[...document.querySelectorAll('[role="tab"]')];
$('section-select').replaceChildren(...sectionTabs.map(tab=>new Option(sourceUIText(tab).trim(),tab.dataset.action)));
$('section-select').onchange=()=>sectionTabs.find(tab=>tab.dataset.action===$('section-select').value)?.click();
const syncSection=()=>{const selected=sectionTabs.find(tab=>tab.getAttribute('aria-selected')==='true');if(selected)$('section-select').value=selected.dataset.action;};
new MutationObserver(syncSection).observe(document.querySelector('[role="tablist"]'),{subtree:true,attributes:true,attributeFilter:['aria-selected']});
