   hydraulics=pipeHydraulics(r,{length:flowToSI(n('length'),'length',$('flow-length-unit').value),roughness:flowToSI(n('roughness'),'diameter',$('flow-roughness-unit').value),localK:n('local-k'),efficiency:n('eta')/100,heightDifference:n('height'),pressureDifference:flowToSI(n('pressure-difference'),'pressureDrop',$('flow-pressure-difference-unit').value)});
