  const values={'rho':'1000','rho-unit':'kgm3','viscosity':'.001','visc-unit':'Pas','value':kind==='laminar'?'.1':'2','unit':'ms','diameter':kind==='laminar'?'.01':'.05','diameter-unit':'m','hydraulics':'on','length':kind==='laminar'?'10':'100','length-unit':'m','roughness':kind==='laminar'?'0':'.05','roughness-unit':'mm','local-k':kind==='laminar'?'0':'3','eta':'80','height':'0','pressure-difference':'0','pressure-difference-unit':'kPa'};
