 $('cl-builder').onsubmit=e=>{e.preventDefault();const draft={...cycleLibraryState.builder};ccLibraryRun('build',r=>{const input={...draft};for(const k of RANKINE_LIBRARY_TYPES.includes(draft.kind)?['mass','pLow','pHigh',...(draft.kind==='rankine-regenerative'?['pBleed']:[]),...(draft.equipment==='actual'?['etaPump','etaHP',...(draft.kind==='rankine-regenerative'?['etaPumpHigh']:[]),...(['rankine-reheat','rankine-regenerative'].includes(draft.kind)?['etaLP']:[])]:[]),...(draft.steamMode==='superheated'?['Tsteam']:[]),...(draft.kind==='rankine-reheat'?['pReheat','Treheat']:[])]:['p1','T1','mass','ratio',draft.kind==='carnot'?'Tlow':draft.heatMode==='heat'?'heat':'Tmax'])input[k]=parseNumber(input[k]);return r.libraryCycle(readLibraryCycleConfig(input));},q=>{ccApplyLibrary(q.result);$('cl-name').value=libraryCycleName(draft.kind,uiTranslator.language==='en');cycleLibraryState.label=$('cl-name').value;ccSyncDraft();});};
 $('cl-save').onclick=()=>ccLibraryTry(()=>{const template=ccLibraryCurrent();if(cycleLibraryState.templates.some(t=>t.name===template.name))throw Error(t('Назва вже зайнята.','Name already exists.'));if(cycleLibraryState.templates.length>=8)throw Error(t('Максимум 8 власних шаблонів.','Maximum 8 personal templates.'));cycleLibraryState.templates.push(template);ccLibraryList();$('cl-saved').value=template.name;ccSyncDraft();$('cl-status').textContent=t('Шаблон збережено у проєкті.','Template saved in the project.');});
 $('cl-load').onclick=()=>ccLibraryTry(()=>{const template=cycleLibraryState.templates.find(q=>q.name===$('cl-saved').value);if(!template)throw Error(t('Оберіть збережений шаблон.','Select a saved template.'));ccLibraryOpen(template);});
